quests[9131] = { id = 9131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindung des Schreckenspanzers", description = "Habt Ihr jemals Schreckenspanzerrüstung zu Gesicht bekommen, {class}? Nein, natürlich nicht. Ihr seid immer noch ein <Junge/Mädchen> – ein Dreikäsehoch eben. Ich muss Euch sagen, es ist herrlich.\n\nIhr fragt Euch wahrscheinlich, was all das mit Euch zu tun haben soll, richtig? Hört gut zu, <Anfänger/Anfängerin>: Ich brauche Dunkeleisenfragmente und bin bereit zu zahlen, um an so viele Stücke wie möglich zu kommen.\n\nIch benötige die Fragmente für das Zusammensetzen der Schreckenspanzer für unsere Helden. Bringt mir Fragmente, dann werdet Ihr bezahlt.", sourceObjective = "Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 30 Dunkeleisenfragmente.", sourceObjectiveStatus = "unverified-source-field" }
quests[9132] = { id = 9132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkeleisenfragmente" }
quests[9133] = { id = 9133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegt nach Silbermond", description = "{class}, ich könnte Euch für eine ganz geringe Summe auf dem Rücken einer dieser herrlichen Kreaturen rasch durch die Lüfte fliegend an Euer Ziel bringen lassen. Es ist auch viel sicherer, als wenn Ihr zu Fuß gehen würdet, das könnt Ihr mir glauben!\n\nSucht Sathren Morgenblau auf, sobald Ihr in Silbermond angekommen seid.\n\nWendet Euch wieder an mich, wenn Ihr bereit sein solltet, durch die Lüfte zu reisen.", sourceObjective = "Erwerbt einen Flug nach Silbermond und bringt Sathiels Frachtbrief zu Sathren Morgenblau in Silbermond.", progress = "Das ist eine ganz schön lange Liste, die Ihr da habt, mein Freund. Lasst mich mal sehen.", completion = "Was soll das? Sie möchte all das!?\n\nHabt Ihr wenigstens jemanden bei Euch, der Euch beim Rücktransport behilflich ist?", sourceObjectiveStatus = "unverified-source-field" }
quests[9134] = { id = 9134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmelsmeisterin Abendlicht", description = "Naja, sieht nicht so aus, als hättet Ihr einen Karren oder ein Lasttier dabei, also gebe ich Euch besser nur das, was Ihr auch wirklich tragen könnt. Wenn Ihr bereits mit Himmelsmeister Morgenhell in Morgenluft gesprochen habt, dann solltet Ihr das hier so schnell wie möglich zu Sathiel bringen, indem Ihr dorthin zurückfliegt.\n\nBringt Himmelsmeisterin Abendlicht diese Waren zur Endkontrolle. Ihr findet sie am Hirtentor direkt außerhalb von Silbermond.", sourceObjective = "Bringt Sathiels Waren zu Himmelsmeisterin Abendlicht am Hirtentor direkt außerhalb von Silbermond.", progress = "Wow, dieses Warenpaket sieht aber mächtig schwer aus! Möchtet Ihr all das auf eins meiner Prachtstücke laden?", completion = "Zurück nach Morgenluft in den Immersangwald, ja? Alles klar, ich kann Euch schnell an Euer Ziel bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9135] = { id = 9135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Sathiel", description = "Sieht aus, als ob alles klar geht.\n\nSo, die Frage ist, habt Ihr schon mit meinem Kollegen, Himmelsmeister Morgenglanz, gesprochen? Wenn ja, dann zahlt Ihr ganz einfach die kleine Gebühr und fliegt rasch zurück.\n\nLasst mich wissen, wenn Ihr bereit seid.", sourceObjective = "Erwerbt einen Flug zurück nach Morgenluft im Immersangwald und liefert Sathiels Waren bei Sathiel ab.", progress = "{class}, schon zurück? Das kann aber unmöglich alles sein, was auf der Liste stand!", completion = "Hmmm, wenn er gesagt hat, dass der Rest schnell über den Landweg nachgeliefert wird, dann will ich ihn mal beim Wort nehmen. In der kurzen Zeit, in der wir zusammen gearbeitet haben, hat er es noch immer geschafft, die Waren pünktlich zu liefern.\n\nIch danke Euch, {name}. Hier, nehmt diese Münzen... sie haben schon den ganzen Tag in meiner Tasche geklimpert.", sourceObjectiveStatus = "unverified-source-field" }
quests[9136] = { id = 9136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildpflanzen", description = "Ich fertige für die mutigen Helden, die sich nach Naxxramas begeben, eine spezielle Rüstung an - die Rüstung des Traumwandlers. Sie versorgen mich zwar schon mit den meisten Materialien, die ich dafür benötige, aber ich halte dennoch nach jenen Ausschau, die in der Lage sind, mir Wildwedel aus dem Pflanzenreich unserer Welt zu besorgen.\n\nIhr denkt vielleicht, dass diese Aufgabe unter Eurer Würde ist, aber ohne diese Wedel kann die Rüstung nun mal nicht hergestellt werden.\n\nIch bin außerdem in der einzigartigen Lage, Euch mit einem Insigne Eurer Wahl zu bezahlen, da mich die Argentumdämmerung und der Kreuzzug mit den entsprechenden Mitteln unterstützen.", sourceObjective = "Rayne bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 30 Wildwedel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9137] = { id = 9137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildwedel" }
quests[9138] = { id = 9138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnenkuppe", description = "Wir sind hier eingekesselt, {class}! Die anderen Dörfer wurden alle von der Geißel überrannt!\n\nIhr müsst umgehend nach Nordosten, in das Dorf Sonnenkuppe reisen und Euch dort den nerubischen Truppen der Geißel stellen. Es ist unmöglich sie zu verfehlen - sie sehen aus wie riesige Spinnen.\n\nWir dürfen keine Zeit verlieren! Quel'Thalas muss zurückerobert werden!", sourceObjective = "Tötet 10 nerubische Wachen und kehrt anschließend zu Arkanist Vandril in Tristessa in den Geisterlanden zurück.", completion = "Hervorragend! Doch es gibt noch viel zu tun, bis auch der letzte Rest dieser Landplage namens Geißel aus dem mächtigen Quel'Thalas vertrieben wurde!\n\nHier, Eure Bezahlung... Es ist zwar nicht viel, doch Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[9139] = { id = 9139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldnebel", description = "Wir haben unseren ersten Sieg errungen, doch es warten noch zwei weitere Dörfer auf ihre Befreiung!\n\nDas Dorf Goldnebel ist unser nächstes Ziel. Es liegt im Nordwesten und wurde von den Geistern der Hochelfen besetzt, die dort einst lebten. Grauenerregend, ich weiß, allerdings scheint dies eine der bevorzugten Taktiken zu sein, derer sich die Geißel bedient.\n\nZieht los und besiegt diese Geister und Gespenster, {class}. Folgt der westlichen Straße, die aus Tristessa hinaus führt und Ihr werdet das Dorf finden.", sourceObjective = "Besiegt 6 Geister der Quel'dorei und 4 Gespenster der Quel'dorei. Kehrt anschließend zu Arkanist Vandril in Tristessa in den Geisterlanden zurück.", completion = "Euer Erfolg in Goldnebel bringt uns wieder einen Schritt näher an die vollständige Rückeroberung unserer Ländereien. Doch lasst Euch nicht täuschen, {class}, diese Schlacht ist noch lange nicht geschlagen.\n\nHier, diese Belohnung habt Ihr Euch mehr als verdient. Sie wird sich als nützlich erweisen, sobald Ihr nach Windläuferdorf aufbrecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9140] = { id = 9140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windläuferdorf", description = "{name}, der entscheidende Kampf um die Dörfer der Geisterlande steht kurz bevor. Windläuferdorf im Südwesten wurde von einer großen Armee aus den besten Sturmtruppen der Geißel, Schemengeister und Gargoyles überrannt. Ihr werdet als Speerspitze unserer Offensive fungieren und die Zahl ihrer Kämpfer dezimieren.\n\nDie Magister vom Sanktum der Sonne haben uns einen besonderen Auftrag erteilt; sie würden gerne die Überreste der Geißel studieren, um neue Wege zur Bekämpfung dieser Plage zu finden.\n\nGute Jagd!", sourceObjective = "Sammelt 6 geisterhafte Substanzen und 4 Gargoylefragmente und bringt sie zu Arkanist Vandril in Tristessa in den Geisterlanden.", progress = "{class}, wurde das Windläuferdorf befreit? Diese verdammten Magister des Sanktums der Sonne fordern ständig von mir, dass ich ihnen endlich Überreste der Geißel gebe, die Ihr gerade für mich sammeln sollt.\n\nMacht Euch deshalb aber keine Sorgen! Nehmt Euch alle Zeit, die Ihr braucht, um diesen Auftrag sicher zu Ende zu führen. Ich kümmere mich derweil um die Magister.", completion = "Ihr habt es geschafft, {name}. Ihr habt drei Dörfer aus der Umklammerung der Geißel befreit! Nun können wir uns voll und ganz auf die Bekämpfung der Geißel in der Todesschneise und südlich bei der Todesfestung konzentrieren.\n\nSucht Euch eine dieser Belohnungen aus. Ich hoffe, Ihr bleibt noch ein Weilchen. Wir können Eure Hilfe auch weiterhin gut gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9141] = { id = 9141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie nennen mich \"den Schleifer\"", description = "Ihr wollt eine Verfügung? Ihr erwartet von mir, Euch eine heißbegehrte Arbeitsanweisung einfach so auszuhändigen? Ich glaube nicht, Knirps. Handwerker aus der ganzen Welt bewerben sich um Aufträge hier an der Front.\n\nWenn Ihr eine Arbeitsanweisung wollt, zeigt mir, dass Ihr gewillt seit, für die Sache zu bluten! Bringt mir eine Ehrenmarke, dann können wir darüber reden.\n\nUnd es gibt nur einen Weg, so eine Marke in Eure schmutzigen kleinen Pfoten zu bekommen - geht kämpfen.", sourceObjective = "Einsatzkommandant Metz bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte eine Ehrenmarke der Argentumdämmerung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9142] = { id = 9142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung" }
quests[9143] = { id = 9143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maßnahmen gegen Zeb'Sora", description = "Unser Leutnant hier hat uns einfach angreifen lassen, ohne sich vorher ein Bild über die taktische Lage zu machen. Die Trolle lauerten bereits jenseits des Sees auf uns. Durch seine Unfähigkeit wurden wir einfach dahingemetzelt! Hoffentlich hörst du auch zu, Tomathren? Dämlicher Idiot!\n\nWerdet Ihr uns helfen, {class}? Diese Trolle sind immer noch dort draußen. Ich werde hier bei unserem Leutnant bleiben - ich glaube, er hat seinen Verstand verloren.\n\nGeht nach Zeb'Sora im Osten auf der andere Seite des Sees. Ich will Rache! Bringt mir ihre Ohren, damit ich mir eine nette Halskette anfertigen kann!", sourceObjective = "Sammelt 6 Trollohren von Zeb'Sora und bringt sie zu Waldläuferin Valanna in den Geisterlanden.", progress = "Habt Ihr die Trollohren?\n\nWisst Ihr, wenn wir ab und an mal etwas Unterstützung aus Tristessa erhalten würden, wäre die ganze Misere hier so nie passiert. Ich bin wirklich froh über Euer Kommen.", completion = "Ich schätze Eure Bemühungen, {class}! Habt Dank. Wenigstens können wir jetzt sagen, dass diese ganze Expedition und die vielen Opfer nicht vergebens gewesen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[9144] = { id = 9144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollen in den Geisterlanden", description = "Mein Neffe wurde vor einigen Tagen in die Geisterlande entsandt. Er hat nicht von seinem Auftrag gesprochen, nur, dass es sich um etwas extrem Geheimes handelt.\n\nEr kehrte nie zurück, und ich befürchte das Schlimmste, {class}. Ein vermisster Bote mag den hartherzigen Magistern von Silbermond nicht viel bedeuten, aber er ist wie ein Sohn für mich. Ich bitte Euch, {name}, sucht nach ihm.", sourceObjective = "Folgt der Straße, die von Morgenluft aus nach Süden führt, und haltet Ausschau nach Kurier Morgenwandler, wenn Ihr die Geisterlande erreicht.", completion = "Helft mir, Fremder. Ich muss... Tristessa... erreichen... Ich darf nicht versagen.\n\n<Der Blick des Blutelfen entschwindet ins Leere, und er versinkt wieder in Bewusstlosigkeit.>", sourceObjectiveStatus = "unverified-source-field" }
quests[9145] = { id = 9145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Waldläuferin Valanna!", description = "{class}, ich kann hier nicht einfach rumsitzen und auf eine Audienz mit dem Hochexekutor oder der Dame Auriferous warten! Diese Angelegenheit duldet keinen Aufschub!\n\nWir hatten den Auftrag, uns um die Waldschattentrolle von Zeb'Sora im Nordosten jenseits des Elrendarsees zu kümmern. Doch unser Leutnant hat den Angriff falsch geplant und wir haben hohe Verluste erlitten. Kurz nach der Attacke ist er dann zusammengebrochen. Waldläuferin Valanna hat mich hierher und Waldläuferin Salissa in die Enklave der Weltenwanderer entsandt, um Verstärkung anzufordern.\n\nIhr müsst unsere Einheit finden, {class}! Valanna ist schwer verletzt und der Leutnant ist nur noch ein plapperndes Mündel.", sourceObjective = "Findet Waldläuferin Valanna und Leutnant Tomathren am Ufer des Elrendarsees nahe Sonnenkuppe in den Geisterlanden.", completion = "Es ist gut zu hören, dass Lethvalin sich in Sicherheit bringen konnte, und dass er Euch um Hilfe gebeten hat, anstatt einfach nur abzuwarten.\n\nHoffentlich konnte sich Waldläuferin Salissa zur Enklave der Weltenwanderer durchschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9146] = { id = 9146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Hauptmann Helios", description = "Ihr müsst mir einen letzten Gefallen tun, {class}. Für den Fall, dass Waldläuferin Salissa es nicht bis zur Enklave der Weltenwanderer am südlichen Ausläufer des Sees geschafft hat, möchte ich, dass Ihr dorthin reist und Hilfe holt.\n\nMeldet Euch einfach bei Hauptmann Helios und lasst ihn wissen, was hier geschehen ist. Sicherlich wird er uns schnellstmöglich Hilfe schicken.", sourceObjective = "Sprecht mit Hauptmann Helios bei der Enklave der Weltenwanderer am südlichen Ufer des Elrendarseese in den Geisterlanden.", completion = "Das sind in der Tat schlechte Nachrichten - Ich habe Tomathrens Führungsqualitäten völlig überschätzt. Ich werde sofort einen Kampftrupp entsenden, um ihn und Valanna sicher zurückzubringen.\n\nUnglücklicherweise haben wir nichts mehr von Waldläuferin Salissa gehört, ich befürchte das Schlimmste.\n\nIhr habt den Weltenwanderern heute einen wertvollen Dienst erwiesen, {class}. Bitte nehmt dies als Zeichen unserer Wertschätzung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9147] = { id = 9147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der sterbende Kurier", description = "Was steht Ihr hier herum? Seht Ihr nicht, dass Ihr Euch um diesen Jungen sofort kümmert müsst? Wie es aussieht, hat die Seuche seinen Körper jetzt gänzlich befallen. In wenigen Minuten kann nicht einmal eine Apothekermeisterin wie ich ihn noch retten.\n\nDas Blut der Tiere südlich des Flusses ist bereits verseucht. Geht über die Brücke und jagt dort die befallenen Biester. Bringt mir genügend verseuchte Blutproben und ich werde daraus ein Serum gewinnen, das diesen Blutelfen retten kann. Beeilt Euch!", sourceObjective = "Apothekerin Thedra im Immersangwald möchte, dass Ihr ihr 4 verseuchte Blutproben von Tieren aus den Geisterlanden bringt.", progress = "Und? Habt Ihr, was ich benötige? Beeilt Euch oder mit dem hübschen {race} ist es gleich aus!", completion = "Gerade noch rechtzeitig, {name}! Ich war drauf und dran für unseren Freund hier ein schönes Loch auszuheben.\n\nMein Trank scheint zu wirken; er kommt wieder zu sich.\n\nHey, ich glaube er will Euch etwas sagen. Warum versucht Ihr nicht mal mit ihm zu sprechen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9148] = { id = 9148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zustellung nach Tristessa", description = "Ich... ich bin zu schwach... ich kann nicht mehr weiter. Ich trage eine finstere Warnung vom Lordregenten Theron bei mir, einen Brief, um genau zu sein. Ihr müsst ihn für mich überbringen.\n\nBringt ihn zu Arkanist Vandril in Tristessa. Die Stadt liegt weiter im Süden entlang dieser Straße. Geht dorthin... und findet Vandril...", sourceObjective = "Bringt den Brief aus Silbermond zu Arkanist Vandril in Tristessa in den Geisterlanden.", progress = "Ihr habt den Brief?", completion = "Endlich! Wir haben schon seit Wochen auf eine Antwort vom Lordregenten gewartet! Lasst mich mal sehen...\n\n<Vandril beginnt den Brief zu lesen.>\n\nWas soll das? Eine finstere Präsenz? Er spürt eine finstere Präsenz in den Geisterlanden?! Im Ernst, das hätte ich ihm auch sagen können!\n\nIst das die Nachricht, auf die wir gewartet haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[9149] = { id = 9149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verseuchte Küste", description = "Um ein Heilmittel gegen die Seuche finden zu können, müssen wir verstehen, wie sie sich auf verschiedene Kreaturen auswirkt: von den komplexesten Lebensformen bis hin zu niedrigen Untergattungen.\n\nIch kam hierher, um die Murlocs zu untersuchen, da sie, wie wir, ihren freien Willen auch im Untotendasein erhalten haben. Was ist an diesen einfachen Biestern nur so besonders? Ich muss es herausfinden, {name}!\n\nReist nach Nordwesten und bringt mir ihre Rückgrate, damit ich die Ablagerungen der Seuche in ihrem Knochenmark studieren kann. Wer weiß was für Geheimnisse diese kleinen Knochen in sich bergen?", sourceObjective = "Bringt 6 verseuchte Murlocrückgrate zu Apotheker Renzithen in Tristessa in den Geisterlanden.", progress = "Habt Ihr die Exemplare, um die ich Euch gebeten habe, {name}?", completion = "Ausgezeichnet! Diese Rückgrate sind für meine Untersuchungen von unschätzbarem Wert! Sollte ich ein Heilmittel gegen die Seuche finden und meinem Namen dadurch Ruhm verleihen, werde ich nicht vergessen, Euch zu erwähnen!\n\nBis dahin, nehmt dies als Belohnung. Ihr könntet davon Gebrauch machen, solltet Ihr noch einmal zur Küste gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9150] = { id = 9150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum vergessenen Sanktum", description = "Glaubt Ihr das, {name}? Momentan gibt es ein funktionstüchtiges arkanes Sanktum, das südöstlich von hier im Einsatz ist, das Sanktum der Sonne. Alle Magister, die sich für wichtig halten, möchten an dessen Unterhaltung beteiligt sein.\n\nDas Sanktum des Mondes im Westen haben natürlich alle vergessen. Es ist nicht mehr viel davon übrig und seine Energien haben merkwürdige Kreaturen erweckt.\n\nIch bin niemand, der gute Ressourcen einfach so verkommen lässt! Geht zum Sanktum des Mondes und versucht kristallisierte Essenzen von den Kreaturen dort zu erlangen.", sourceObjective = "Magister Darenis möchte, dass Ihr zum Sanktum des Mondes westlich von Tristessa reist und dort 8 kristallisierte Manaessenzen von den dort hausenden Arkanverschlingern und Manaschleichern erlangt.", progress = "Habt Ihr die Essenzen, {name}?", completion = "Sie sind in einem bemerkenswert guten Zustand, {name}. Ich bin mit Eurer Arbeit sehr zufrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9151] = { id = 9151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sanktum der Sonne", description = "Ihr habt Eure Loyalität gegenüber Tristessa bewiesen und uns geholfen, gegen die Geißel zu kämpfen. Einige unserer mächtigsten Magister sind aus Silbermond gekommen, um uns dabei zu helfen, den Feind vor seiner eigenen Schwelle zu bekämpfen.\n\nSie haben das arkane Sanktum im Süden wiedererrichtet und die Geißel aus der umliegenden Gegend vertrieben. Sie planen einen Angriff auf die Todesfestung, Dar'kahns Stützpunkt. Ihr solltet sie unterstützen, {name}. Ich bin mir sicher, dass <ein erfahrener/eine erfahrene:c> {class} wie Ihr hier eine echte Hilfe wäre.", sourceObjective = "Sprecht mit Magister Idonis im Sanktum der Sonne in den Geisterlanden.", completion = "Darenis schickt Euch? Gut, ich schätze, wir können Euch im Kampf gegen Dar'khans Streitmächte brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9152] = { id = 9152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tombers Vorräte", description = "Wie soll ich die Kriegsvorbereitungen mit Vorräten unterstützen, wenn ich sie nicht mal sicher hierher bringen kann? Man hat mir Geleitschutz versprochen, der niemals kam. Ich musste dann auch noch einen meiner Karren zurücklassen, als ich von einer Bande Ghule im Westen angegriffen wurde!\n\nWollt Ihr mir vielleicht helfen, damit ich mein Geschäft auch eröffnen kann? Geht die westliche Straße, die aus der Ortschaft führt, runter und am Friedhof vorbei. Auf der anderen Seite der Todesschneise liegt eine Verzweigung. Der Hügel, auf dem ich meinen Karren lassen musste, liegt kurz dahinter.", sourceObjective = "Erlangt Rathis Tombers Vorräte und kehrt zu ihm in Tristessa in den Geisterlanden zurück.", progress = "Sobald ich den Rest meiner Vorräte habe, kann ich mein Geschäft aufnehmen. Die Streitkräfte werden nicht weit kommen, wenn sie nicht das erhalten, womit sie regelmäßig ihren Handel treiben.\n\nKriegsgebiete können so florierend für das Geschäft sein, findet Ihr nicht auch, {class}? So, habt Ihr Euch einen Weg durch all die Ghule zu meinem Karren bahnen können?", completion = "Dank der restlichen Vorräte hier, kann ich jetzt endlich mit meinem Geschäft loslegen. Ich bin mir sicher, dass der Hochexekutor erfreut sein wird, sobald er hört, dass der Krieg gegen Dar'Khan und die Geißel beginnen kann.\n\nNatürlich gibt es da auch noch Eure Belohnung. Nun gut, {class}, hier ist die von mir erwähnte Münze. Solltet Ihr irgendwelche Handwerkswaren benötigen, schaut einfach vorbei.", sourceObjectiveStatus = "unverified-source-field" }
quests[9153] = { id = 9153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohliche Schatten", description = "Die schwebenden Nekropolen der Geißel setzen die Territorien der Horde genauso unter Druck wie die der Allianz. Tanaris, die Verwüsteten Lande, Winterquell und die Brennende Steppe erzittern unter den Schatten der fliegenden Festungen.\n\nNur durch unser gemeinsames Handeln können wir sie zurückschlagen.\n\nJede Nekropole wird durch magische Zirkel unterstützt, die sich in der Nähe befinden und um die sich ein Schwarm untoter Kreaturen versammelt. Wir haben herausgefunden, dass wir die Verteidigung rund um die Zirkel zerstören können, indem wir die geistlosen Horden vernichten.", sourceObjective = "Benutzt Eure Karte, um von der Geißel angegriffene Gebiete ausfindig zu machen. Geht dorthin und beschädigt eine Nekropole, indem Ihr die Truppen der Geißel, die sie umgeben, besiegt. Bringt 10 ihrer nekrotischen Runen zu Kommandant Thomas Helleran bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9154] = { id = 9154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapelle des Hoffnungsvollen Lichts", description = "Die Geißel ist in größerer Anzahl zurückgekehrt, als wir es jemals zuvor gesehen haben. Dies müssen die Machenschaften des Lichkönigs sein! Deshalb rekrutiert die Argentumdämmerung alle Männer und Frauen, die fähig und bereit sind, unsere Länder zu verteidigen.\n\nFalls Ihr unserer Sache dienen wollt, dann bringt dieses Dokument zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjective = "Bringt den Ruf zu den Waffen zum Bewahrer der Schriften in der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9155] = { id = 9155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entlang der Todesschneise", description = "Da Ihr es bis hierher geschafft habt, habt Ihr bestimmt schon mal von der Todesschneise gehört und dass selbst jetzt, Jahre nachdem Arthas sie während seines Feldzuges nach Silbermond erschaffen hat, die geistlosen Kreaturen der Geißel noch immer auf ihrem Pfad wandeln.\n\nMacht Euch nützlich und dünnt die Anzahl der Geißel innerhalb der Schneise etwas aus. Falls Ihr Euch als fähig erweist, lege ich ein gutes Wort für Euch ein.", sourceObjective = "Tötet 10 hungrige Auferstandene und 10 gegeißelte Kannibalen in der Todesschneise. Kehrt anschließend zu Todespirscher Rathiel in Tristessa zurück, um Eure Belohnung zu erhalten.", completion = "Nicht schlecht, {name}. Macht weiter so! Leute wie Euch können wir immer gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9156] = { id = 9156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Faulbein und Luzran", description = "Hiermit ist ein Kopfgeld auf die Monstrositäten Faulbein und Luzran ausgesetzt. Diese abscheulichen Kreaturen von Dar'Khan sind sehr gefährlich, und wurden in der Nähe der Heulenden und Blutenden Ziggurats auf Patrouille gesehen. Personen, welche die Belohnung einfordern wollen, müssen die Köpfe der Monstrositäten als Beweis zu Todespirscher Rathiel bringen.", sourceObjective = "Sucht in den Geisterlanden nach Faulbein und Luzran. Bringt ihre Köpfe zu Todespirscher Rathiel in Tristessa, um eine Belohnung zu erhalten.", progress = "Ihr habt etwas, das Ihr mir zeigen wollt, {name}?", completion = "Aha! Luzran und Faulbein! Jetzt seht ihr nicht mehr so gefährlich aus, was? Aber immer noch genauso hässlich!\n\nNehmt dies als Belohnung, {name}. Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[9157] = { id = 9157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergessene Rituale", description = "Jedes Jahr haben wir, die Einwohner von Sonnenkuppe, an einem Ritual teilgenommen, um die verschiedenen Aspekte der Natur unter unserer Kontrolle zu halten. Die Herrschaft über das Wasser wurde symbolisiert durch die Beschwörung und Versklavung eines Wasserelementars namens Aquantion. Aber es gelang ihm, unsere Magie gegen uns zu wenden, seine Fesseln abzuwerfen und stattdessen uns zu versklaven!\n\nWährend des Rituals trugen wir wellenförmige Medaillons. Sucht sie auf dem Grund des Sees, wir benötigen sie, um die Geister meiner Kameraden zu befreien!", sourceObjective = "Bringt 8 Wellenfrontmedaillons zu Geranis Weißflor in den Geisterlanden.", progress = "Konntet Ihr die Medaillons beschaffen, {name}? Die Ertrunkenen suchen immer noch diesen See heim!", completion = "Mithilfe dieser Halsketten werden wir Aquantion erneut beschwören. Der rebellische Elementar wird bezahlen und unser Tod wird gerächt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[9158] = { id = 9158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überträger der Seuche", description = "Eure Anwesenheit in den Geisterlanden zeugt von großem Mut, {name}. Hier gibt es so viel zu erledigen und nur wenige mutige Seelen, die uns zur Seite stehen.\n\nIch habe eine undankbare Aufgabe für Euch, sofern Ihr geneigt seid, unserer Sache zu dienen. Die gesamte Fauna wurde von der Seuche befallen und wir müssen ihre weitere Ausbreitung stoppen. Jagt die Geisterklauenluchse östlich und südlich von hier und kehrt zu mir zurück, nachdem Ihr eine ausreichende Zahl erlegt habt.", sourceObjective = "Weltenwanderin Sedina in der Enklave der Weltenwanderer in den Geisterlanden möchte, dass Ihr 10 Geisterklauenluchse erschlagt.", completion = "Ihr habt Euch bewährt, {name}. Es ist von größter Wichtigkeit, dass die Seuche nicht auch noch die gesunde Fauna des Immersangwalds befällt. Ich habe noch weitere Aufgaben für Euch, sofern Ihr noch auf der Suche nach Arbeit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[9159] = { id = 9159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebietet der Seuche Einhalt", description = "Ihr habt Euch als würdiger Verbündeter erwiesen, {name}. Ihr müsst mit Eurer Aufgabe fortfahren und weitere verseuchte Wildtiere erlegen. Dieses Mal werdet Ihr Euch die etwas gefährlicheren Exemplare vornehmen. Jagt Spindelweberlauerer westlich der Todesschneise und Vampirnebelfledermäuse direkt südlich von hier. Kehrt anschließend zu mir zurück.", sourceObjective = "Weltenwanderin Sedina in der Enklave der Weltenwanderer in den Geisterlanden möchte, dass Ihr 8 Spindelweberlauerer und 10 Vampirnebelfledermäuse erschlagt.", completion = "Ihr habt Eure Aufgabe sehr ernst genommen und daher möchte ich Euch entsprechend belohnen. Wir brauchen mehr Verbündete mit Eurer Hingabe und Tapferkeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9160] = { id = 9160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersucht An'daroth", description = "{class}, wir haben einige Schwierigkeiten mit einer Gruppe von Nachtelfen, die erst kürzlich eine der naheliegenden Inseln besetzt hat. Sie haben ein kleines Lager an dem alten hochelfischen Leyliniennexus, An'daroth, im Nordwesten aufgeschlagen. Es gibt einen kleinen schlammigen Pfad, der hinter der Todesschneise dorthin führt.\n\nIch würde vorschlagen, dass Ihr uns helft, indem Ihr Euch dorthin begebt und herausfindet, was sie vorhaben. Tötet bei der Gelegenheit so viele dieser eingebildeten Nachtelfen, wie Ihr könnt.", sourceObjective = "Untersucht das Gebiet um An'daroth, tötet 12 Spione der Schildwache und kehrt anschließend zu Dame Auriferous in Tristessa in den Geisterlanden zurück.", completion = "Es ist enttäuschend, dass es keine offensichtlichen Hinweise auf die Pläne der Nachtelfen bei An'daroth gab. Wie auch immer, diese Bäume, welche aussahen wie kleine magisch gewachsene Bäume mit Energiekugeln auf ihrer Spitze, sind äußerst interessant. Es scheint mir, als müssten wir die Art unserer Informationsbeschaffung ein wenig direkter gestalten.\n\nHier, nehmt diese Münze und die Tränke. Vermutlich werdet Ihr sie noch brauchen, bevor wir diese Angelegenheit mit den Nachtelfen geklärt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9161] = { id = 9161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten des Verräters", description = "Man sagt, Dar'Khan Drathir sei von den Toten wiederauferstanden, um über die Armeen der Geißel in den Geisterlanden zu herrschen. Schon vor langer Zeit hatte sich Dar'Khan mit der Geißel eingelassen... damals war er noch ein lebender, atmender Elf. Er verbrachte viel Zeit in den Gemäuern des Morgensternturms, nordöstlich von hier. Dort verbarg er sich viele Nächte lang, ersann finstere Machenschaften gegen sein eigenes Volk.\n\n{name}, durchsucht den Turm nach weiteren Informationen. Vielleicht hatte er seine Pläne niedergeschrieben, oder er führte ein Tagebuch. Wer weiß schon, wo nützliche Hinweise auf Ihre Entdeckung warten.", sourceObjective = "Begebt Euch in die Geisterlande zum Morgensternturm und sucht nach möglichen Hinweisen auf Dar'Khans Vergangenheit.", completion = "Ihr blättert durch die ersten Einträge des uralten Buchs und kommt zu dem Schluss, dass es einst der Person gehörte, die heute als Dar'khan Drathir bekannt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[9162] = { id = 9162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergangenheit erwacht", description = "Als Ihr durch die Einträge des Tagebuchs blättert, bekommt Ihr das unbestimmte Gefühl, beobachtet zu werden.\n\nDas Geschriebene beunruhigt Euch. Dar'Khans Seele scheint erfüllt von Hass und Verachtung für sein eigenes Volk. Das ganze Ausmaß seiner Machenschaften und Intrigen wird auf diesen Seiten ausführlich beschrieben.\n\nEiniges davon wird Vynna sicherlich sehr nützlich finden.", sourceObjective = "Kehrt mit Dar'Khans Tagebuch zu Waldläuferin Vynna bei der Enklave der Weltenwanderer in den Geisterlanden zurück.", progress = "Sagt mir, {name}, was habt Ihr herausgefunden?", completion = "Diese Information ist für uns von hohem Wert, {name}. Wir alle wussten von Dar'Khans Plänen, die Macht des Sonnenbrunnens für die Geißel zu stehlen, doch vieles auf diesen Seiten ist völlig neu für uns. Magister Kaendris beim Sanktum der Sonne wird sich sicherlich sehr dafür interessieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[9163] = { id = 9163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In besetztem Gebiet", description = "Nun, die direkten Maßnahmen, für die wir uns letztlich entschieden haben, um herauszubekommen, was diese verdammten Nachtelfen vorhaben, sehen grob zusammengefasst folgenden Ablauf vor: Landet auf ihrer Insel und nehmt alles mit, das für uns von Interesse sein könnte.\n\nIch möchte, dass Ihr die Straße nach Westen in Richtung der Insel Shalandis nehmt. Sie liegt recht nah an der Küste. Nehmt dort sämtliche Pläne mit, die sie möglicherweise auf der Insel oder auf ihrem Schiff verstaut haben.", sourceObjective = "Stehlt die Nachtelfenpläne: An'daroth, Nachtelfenpläne: An'owyn und Nachtelfenpläne: Auskundschaften der Sin'dorei und kehrt anschließend in die Geisterlande zu Dame Auriferous in Tristessa zurück.", progress = "Was machen unsere Bemühungen, die Nachtelfenverschwörung auf der Insel Shalandis aufzudecken, {class}?", completion = "Äußerst beunruhigend! Die Pläne zeigen die Streitkräfte der Nachtelfen bei An'daroth, von denen wir bereits wussten, doch gibt es wohl eine weitere Gruppe bei An'owyn, einem eher abgelegenen Leyliniennexus im Südosten.\n\nEs existiert noch ein dritter Nexus im Osten, An'telas, der nicht weiter erwähnt wird. Ich habe da ein ganz mieses Gefühl bei der Sache, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9164] = { id = 9164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene der Todesfestung", description = "Ah, ja. Ich besitze ein Gebräu, das jeglichen Betäubungseffekten, die durch alchemistische Mittel verursacht werden, entgegenwirkt.\n\nEs kann zu Nebeneffekten wie Verwirrung und Übelkeit kommen, in wenigen Fällen führt es zu zeitweiser Blindheit. Doch wenn Ihr mich fragt, ist das alles immer noch besser als das, was die Geißel den Gefangenen in der Todesfeste antun wird.\n\nViel Glück, <mutiger/mutige:c> {class}. Ihr werdet es brauchen.", sourceObjective = "Nehmt Janedas Regenerationsgebräu und begebt Euch zur Todesfestung. Befreit dort Lehrling Varnis, Apothekerin Enith und Waldläufer Vedoran. Kehrt danach zu Arkanistin Janeda beim Sanktum der Sonne zurück, um Eure Belohnung zu erhalten.", completion = "Ich danke Euch, {name}. Ohne Eure Hilfe hätten diese Gefangenen ihren Verstand und ihre Seele an die Geißel verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[9165] = { id = 9165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfügung des freien Geleits", description = "Ohne die Hilfe von Euch Abenteurern, hätte meine Karawane es niemals geschafft! Die Geißelsoldaten, die uns im Unterholz aufgelauert haben, wollten wohl nicht, dass wir hier in einem Stück eintreffen.\n\n<Wache Didier wischt sich den Schweiß von der Stirn.>\n\nJetzt werden wir erst einmal hier warten, bis Feldmarschall Kammerer eintrifft. Er wird Eure Verfügung für freies Geleit unterzeichnen, die Ihr dann zu Einsatzkommandant Metz an der Kapelle des Hoffnungsvollen Lichts bringen könnt.\n\nUnd {name}, achtet in der Gegenwart von Kammerer auf Eure Worte. Er ist ein Mensch der Sorte 'Ich reiße Euch den Kopf ab und breche Euch sämtliche Knochen'... mit dem Unterschied, dass er es auch wirklich tut...", sourceObjective = "Bringt die unterschriebene Verfügung des freien Geleits zu Einsatzkommandant Metz an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9166] = { id = 9166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt die Pläne nach An'telas", description = "Bringt die Nachtelfenpläne für mich nach An'telas. Es liegt östlich von hier, auf dem südlichen Hang des Sonnenhügels, nordöstlich vom Sanktum der Sonne.\n\nMagister Sylastor führt dort diverse Experimente mit den Energien des Leyliniennexus durch, um potentielle Verwendungsmöglichkeiten im Kampf gegen die Geißel zu finden. Zeigt ihm die Pläne, möglicherweise kann er etwas Licht in die Sache bringen und herausfinden, was die Nachtelfen vorhaben.", sourceObjective = "Bringt die Nachtelfenpläne zu Magister Sylastor bei An'telas in den Geisterlanden.", progress = "Gut, dass Ihr hier seid!", completion = "Es war schrecklich! Nachtelfen! Sie haben einen Mondkristall beschworen und irgendeine Niedertracht geplant. Glücklicherweise konnte ich mich davonschleichen und einige unserer Späher und Zauberer aus dem nahegelegenen Sanktum der Sonne zu Hilfe holen. Es gelang uns, die meisten von ihnen zu töten. Die anderen sind daraufhin losgezogen, um die Überlebenden zu jagen!\n\nIch bin so froh, dass Ihr gekommen seid; man hat mich hier nur mit einigen wenigen Spähern zur Verteidigung zurückgelassen!\n\nGebt mir einen Moment, um diese Pläne zu lesen, möglicherweise finde ich heraus, worauf es die Nachtelfen abgesehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9167] = { id = 9167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tod des Verräters", description = "Alles, was wir in den Geisterlanden getan haben, hatte nur ein Ziel, die Rückeroberung all dessen, was rechtmäßig unser ist! Schon zu lange hielt die Geißel diese Region in ihrem Würgegriff.\n\nDie Zeit der Abrechnung ist gekommen, {name}. Dank Eurer Unterstützung und der Hilfe unserer Verbündeten, den Verlassenen, wird die Rache unser sein!\n\nDerjenige, welcher danach trachtete, die Macht des Sonnenbrunnens an sich zu reißen, muss sterben. Begebt Euch zur Todesfestung, der Festung der Geißel südlich der Todesschneise. Bringt mir Dar'Khans Kopf und Eure Taten werden in die Geschichte eingehen!", sourceObjective = "Begebt Euch in die Todesfestung und tötet Dar'Khan Drathir. Bringt anschließend Dar'Khans Kopf zu Magister Kaendris beim Sanktum der Sonne in den Geisterlanden.", progress = "Ist es getan? Wurde Dar'Khan vernichtet?", completion = "Am heutigen Tage habt Ihr der Geißel in dieser Region einen tödlichen Schlag versetzt.\n\nNach dem Tod des schändlichen Verräters ist die Rückeroberung unserer Länder nur noch eine Frage der Zeit. Schon bald werden wir zu altem Ruhm und Glanz zurückgefunden haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[9168] = { id = 9168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Herzen der Todesfestung", description = "Tief in Inneren der Todesfestung führt der Feind magische Experimente zur Erschaffung stärkerer, tödlicherer spektraler Soldaten durch. Diese verabscheuungswürdigen Wesen sind perfekte Tötungsmaschinen, erschaffen von Dar'Khan selbst und verstärkt durch die dunklen Magien der Todesfestung.\n\nBegebt Euch zum Turm der Verdammten im Inneren der Todesfestung und zerstört sie alle, {name}. Wir dürfen es nicht zulassen, dass die Armee des Feindes immer stärker wird, während wir immer noch um die Aufrechterhaltung eines Brückenkopfes in den Geisterlanden kämpfen.", sourceObjective = "Zerstört 8 Augen von Dar'Khan und meldet Euch anschließend bei Magister Idonis am Sanktum der Sonne in den Geisterlanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9169] = { id = 9169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Abschaltung von An'owyn", description = "Die Mondkristalle sind nichts anderes als Seherartefakte - sie wollen uns ausspionieren! Ich weiß, dass An'daroth dafür nicht genügend Energie liefert, doch An'owyn, direkt im Süden, verfügt über genügend Reserven!\n\nDurch die Pläne habe ich einen ungefähren Eindruck darüber gewonnen, wie diese Mondkristalle funktionieren und wir sollten in der Lage sein, sie zu deaktivieren. Allerdings sind sie gesichert, um eine ungewollte Abschaltung zu verhindern. Begebt Euch daher nach An'owyn, beschafft Euch die Kontrollkugel von einem der Nachtelfen und benutzt sie mit den Mondkristallen, um die Durchführung ihrer Pläne zu verhindern!\n\nBeeilt Euch, {class}!", sourceObjective = "Beschafft die Kristallkontrollkugel und benutzt sie, um die nachtelfischen Mondkristalle bei An'owyn zu deaktivieren. Kehrt anschließend zu Magister Sylastor in den Geisterlanden zurück.", completion = "Ich bin erleichtert, {class}! Seid versichert, dass wir ohne Eure Hilfe bei der Abschaltung der Seherkristalle in einer noch viel schwierigeren Lage wären, als wir es sowieso schon sind! Man stelle sich nur vor, umgeben von Feinden und einer von ihnen besäße die Fähigkeit, uns auf Schritt und Tritt zu beobachten!\n\nDank Euch müssen wir uns darüber keine Sorgen mehr machen! Ich habe hier zufällig noch einige Gegenstände herumliegen, für die ich keine weitere Verwendung mehr habe; sicherlich werdet Ihr davon etwas gebrauchen können. Hier, nehmt das als Belohnung.\n\nNochmals vielen Dank, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9170] = { id = 9170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dar'Khans Gefolgschaft", description = "Der verhasste Verräter, Dar'Khan, hat innerhalb der Geißel große Macht erlangt. Seine Gefolgschaft steht an der Spitze gigantischer Heere, die gegen unsere schwindenden Streitkräfte zu Felde ziehen.\n\nMasophet der Schwarze, Jurion der Betrüger, Borgoth der Blutvergießer, Mirdoran der Gefallene. Merkt Euch diese Namen, denn in den Geisterlanden sind diese Männer einzig Dar'Khan gegenüber verantwortlich. Tötet sie und ihre seelenlosen Armeen werden im Chaos versinken.", sourceObjective = "Magister Idonis möchte, dass Ihr Euch zur Todesfestung begebt und Masophet den Schwarzen, Jurion den Betrüger, Borgoth den Blutvergießer und Mirdoran den Gefallenen tötet. Kehrt nach Abschluss Eurer Aufgabe zum Sanktum der Sonne in den Geisterlanden zurück und berichtet ihm.", completion = "Dar'Khans Armeen fallen! Die Geißel kann nicht gegen die vereinte Macht der Sin'dorei und der Verlassenen bestehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9171] = { id = 9171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knusperkost", description = "Das ist unerhört! Ich habe hier keinerlei Zutaten! Mylady hat mich von Silbermond hierher bestellt. Ihr steht schließlich eine Küche zu, wie es sich für ihren Stand geziemt. Nicht? Ich komme der Bitte also nach, aber finde mich hier ohne Vorräte wieder. Ihr müsst für mich losziehen, {class}, und mir frische Beute bringen, damit ich etwas zubereiten kann.\n\nDame Auriferous liebt besonders knusprige Gerichte. Südwestlich, auf der anderen Seite der Todesschneise, gibt es zahlreiche Spindelweberlauerer. Ekelhaft, ich weiß, aber wir müssen nun mal damit zurechtkommen.", sourceObjective = "Sammelt 5 knusprige Spinnenbeine ein und kehrt zu Meisterkoch Mouldier in Tristessa in den Geisterlanden zurück.", progress = "Ich glaube ich kann den Magen der Dame sogar von hier aus knurren hören! Da Ihr hier seid und mich sprechen wollt, gehe ich davon aus, dass Ihr mir meine Zutaten bringt?", completion = "Sehr schön, das dürfte den Zweck erfüllen. Nein, erzählt mir nicht, wie die Dinger rumgekrabbelt sind, ich will es nicht wissen! Ich werde etwas Magie verwenden, dann werden diese Beinchen schon schmackhaft. Ein paar Gewürze, eine Messerspitze Kräuter und natürlich ein paar arkane Zutaten – et voilà, ein passendes Mahl für eine Königin... oder in diesem Fall, eine Dame.\n\nEure Dienste waren zufriedenstellend, {class}. Hier, nehmt dieses Rezept und ein paar Portionen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9172] = { id = 9172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an Magister Kaendris", description = "Die Magister beim Sanktum der Sonne machen große Fortschritte bei ihrer Suche nach den Schwächen der Geißel, nicht zuletzt durch die Hilfe der Verlassenen. Magister Kaendris wird wissen, was mit diesen Informationen zu tun ist.\n\nDas Sanktum der Sonne liegt südwestlich von hier. Ihr müsst Euch beeilen, {name}. Dar'Khan ist ein geschickter Gegner und er beobachtet jeden einzelnen unserer Schritte.", sourceObjective = "Bringt Dar'Khans Tagebuch zu Magister Kaendris beim Sanktum der Sonne in den Geisterlanden.", progress = "Ihr wünscht mit mir zu sprechen?", completion = "Dieses Buch... das ist unmöglich! Es ist Dar'Khans eigene Handschrift. Irgendwo in diesem Buch muss es einen Hinweis geben, der uns eine Schwäche des Gegners aufzeigt.\n\nIhr habt gut daran getan, uns aufzusuchen, {name}. Indem sie diese Angelegenheit in unsere fähigen Hände gaben, haben die Weltenwanderer ihre Weitsicht bewiesen. Diese Rüstung sollte Euch helfen, unsere Sache weiterzuführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9173] = { id = 9173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückeroberung des Windläuferturms", description = "{class}, Ich möchte, dass Ihr den Windläuferturm zurückerobert!\n\nDabei handelt es sich um eine Sache der Ehre. Der Windläuferturm ist die ursprüngliche Residenz von Fürstin Sylvanas Windläufer, Königin der Verlassenen und ehemalige Waldläufergeneralin der Elfen. Aber jetzt wurde der Turm von der Geißel überrannt.\n\nFolgt der Straße nach Süden, bis Ihr zu einer Abzweigung kommt. Wendet Euch dort nach rechts und geht weiter nach Südwesten, wenn Ihr die Todesschneise überquert habt. Dann könnt Ihr den Ort nicht verfehlen.", sourceObjective = "Besiegt 8 Akolythen der Todesfestung und 10 gefallene Waldläufer, dann kehrt zu Hochexekutor Mavren nach Tristessa in den Geisterlanden zurück.", completion = "Ich bin sicher, Fürstin Sylvanas wird über unsere Fortschritte in dieser Sache erfreut sein.\n\nHier, nehmt dies als Bezahlung für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9174] = { id = 9174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aquantion bezwingen", description = "Dieser eigenwillige Elementar hat viele Leben auf dem Gewissen. Indem er die unwürdigen Murlocs dazu brachte, unsere Rituale zu sabotieren, wendete er unsere Magie gegen uns.\n\nZeigt ihm, dass unser Durst nach Rache noch nicht gestillt ist! Nehmt diese Medaillons und legt sie auf den Altar der Gezeitenbeherrschung am Grund des Sees. Aquantion wird Eurem Ruf sofort folgen!\n\nSeid auf der Hut, {race}! Ohne die Kontrolle durch unsere Magie wird sein Zorn ungezügelt sein. Zerstört Aquantion, damit wir ruhen können!", sourceObjective = "Geranis Weißflor möchte, dass Ihr auf den Grund des Sees östlich von Sonnenkuppe taucht und das Bündel mit Medaillons auf den Altar der Gezeitenbeherrschung legt. Beschwört und besiegt den Elementar Aquantion und kehrt zu Geranis zurück.", progress = "Wurde Aquantion schon zerstört?", completion = "Ihr habt unseren Tod gerächt und Aquantions Macht über unsere Seelen gebrochen. Endlich können wir ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9175] = { id = 9175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Halskette der Fürstin", description = "Diese Halskette funkelt, ein bemerkenswertes Schmuckstück, das nicht der Schwermut der Geisterlande zu unterliegen scheint. Auf Grund der Inschrift und des Ortes, an dem Ihr sie gefunden habt, muss es sich dabei um Eigentum von Fürstin Sylvanas Windläufer selbst handeln!\n\nVielleicht wäre es am besten, sie zuerst zu Hochexekutor Mavren nach Tristessa zu bringen? Er scheint der höchstrangige Verlassene in der Gegend zu sein und weiß sicher, was zu tun ist.", sourceObjective = "Bringt die Halskette der Fürstin zu Hochexekutor Mavren nach Tristessa in den Geisterlanden.", progress = "Was habt Ihr da, {name}?", completion = "Ihr sagt, Ihr fandet dies bei einem Schergen der Geißel am Windläuferturm, und dass es eine Inschrift gibt? Lasst mich sehen!\n\nHier, nehmt dies für Eure gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[9176] = { id = 9176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zwillingsziggurats", description = "Glaubt man den Einträgen in seinem Tagebuch, versprach Dar'Khan der Geißel zwei mächtige elfische Artefakte: Den Stein des Lichts und den Stein der Flamme. Beide waren durchdrungen von den magischen Energien des Sonnenbrunnens und verfügten über mächtige Schutzkräfte gegen die Geißel.\n\nMan plante, die Kristalle zu den heutigen Standorten der Heulenden und der Blutenden Ziggurat, inmitten der Todesschneise, zu transportieren. Falls sie dort noch immer aufbewahrt werden, müssen wir sie unbedingt an uns bringen. Ihre Kräfte wären im Kampf gegen die Geißel von großem Nutzen.", sourceObjective = "Reist zur Blutenden und zur Heulenden Ziggurat und bergt den Stein des Lichts und den Stein der Flamme. Kehrt anschließend zu Magister Kaendris beim Sanktum der Sonne in den Geisterlanden zurück.", progress = "Habt Ihr die Kristalle schon geborgen?", completion = "Die Geschichten sind also wahr! Der Stein des Lichts und der Stein der Flamme existieren tatsächlich! Wir werden ihre Macht nutzen, um wirkungsvolle Waffen gegen Dar'Khan zu schmieden.\n\nWenn Ihr die in diesen Artefakten schlummernden Energien zum richtigen Zeitpunkt freisetzt, werden sie Dar'Khan vernichten. Einst wollte er uns diese Macht nehmen, doch jetzt wird sie sein Untergang sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[9177] = { id = 9177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Unterstadt", description = "Wie außergewöhnlich! Es scheint sich um ein Geschenk für Fürstin Sylvanas Windläufer zu handeln, von ihrer Schwester, Alleria!\n\nIhr müsst es sofort zu ihr nach Unterstadt bringen! Die Fürstin residiert im Königsviertel.\n\nUm dorthin zu kommen, benutzt die Translokationskugel im Inneren Sanktum des Sonnenzornturms in Silbermond für den Übergang nach Unterstadt, dann nehmt den Fahrstuhl, um die eigentliche Stadt zu betreten. Schaut auf Eure Karten, wenn Ihr Probleme habt, das Königsviertel zu finden.", sourceObjective = "Bringt die Halskette der Fürstin zu Fürstin Sylvanas Windläufer im Königsviertel von Unterstadt.", progress = "Und Ihr seid?\n\nWas habt Ihr da? Diese Halskette sieht vertraut aus. Gebt sie her!", completion = "<Sylvanas nimmt Euch die Halskette aus der Hand.>\n\nUnmöglich! Nach so langer Zeit dachte ich, sie sei für immer verloren!\n\n<Die Fürstin scheint sich langsam wieder ihrer Umgebung gewahr zu werden und gewinnt ihre Fassung zurück.>\n\nIhr dachtet, dies würde mich erheitern? Denkt Ihr, ich sehne mich nach der Zeit, bevor ich Königin der Verlassenen war? Es bedeutet mir nichts, Alleria Windläufer ist seit langem tot!\n\n<Sie lässt das Amulett auf den Boden fallen.>\n\nGeht mir aus den Augen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9178] = { id = 9178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Verdichteter Gewichtsstein", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-091:\n\n120 verdichtete Gewichtssteine.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 120 verdichtete Gewichtssteine und die Handwerksverfügung für die verdichteten Gewichtssteine zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
