quests[9189] = { id = 9189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an das Grabmal", description = "Ihr habt das Herz der Fürstin gerührt, obwohl es nicht mehr schlägt.\n\nIch habe Anweisungen, die zum Grabmal nach Silberwald gebracht werden müssen. Berater Sorrelon repräsentiert uns und berät dort die Verlassenen.\n\nDie kürzeste Route, wenn man von ihren fliegenden Fledermäusen absieht, ist es, Unterstadt zu verlassen und die Straße nach Süden zu nehmen. Es gibt Wegweiser, also sollte es nicht zu schwer sein, den Ort zu finden. Aber nehmt Euch in Acht, das Grabmal selbst ist eine zerfallene Gruft.\n\nDiese Verlassenen sind schon merkwürdige Kreaturen.", sourceObjective = "Bringt die Befehle der Sin'dorei zu Berater Sorrelon beim Grabmal im Silberwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[9190] = { id = 9190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Runenstoffstiefel", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-635:\n\n8 Runenstoffstiefel.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 8 Runenstoffstiefel und die Handwerksverfügung für die Runenstoffstiefel zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9191] = { id = 9191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Runenstofftasche", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-9999:\n\n8 Runenstofftaschen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 8 Runenstofftaschen und die Handwerksverfügung für die Runenstofftaschen zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9192] = { id = 9192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in den Grubenlichtminen", description = "Die Grubenlichtminen im Südwesten wurden von einem Gnollklan, der sich die Schwarzpfoten nennt, überrannt. Ich muss Euch sicherlich nicht daran erinnern, wie wichtig diese Minen in strategischer Hinsicht für unseren fortwährenden Schlachtzug in den Geisterlanden sind!\n\nNehmt die Straße, die nach Süden führt, und haltet Euch rechts an der Wegzweigung. Kurz nach dem Ziggurat zur Rechten kommt ein kurzer Trampelpfad Richtung Westen. Folgt ihm.\n\nWir brauchen das Erz!", sourceObjective = "Tötet 8 Gnolle der Schwarzpfoten, 6 Strauchdiebe der Schwarzpfoten und 4 Schamanen der Schwarzpfoten. Kehrt anschließend zu Todespirscher Maltendis in Tristessa in den Geisterlanden zurück.", completion = "Da habt Ihr mal ordentlich Blut fließen lassen, {class}. Die Minenarbeiter können jetzt wieder an die Arbeit. Sie sind sicher enttäuscht, dass ihre Pause jetzt vorbei ist, aber wir brauchen nun mal mehr Erz, um Rüstungen und Waffen herzustellen.\n\nHier, nehmt dies als Lohn für Eure pflichtbewusste Tat. Lasst Rüstung und Waffen reparieren und trinkt einen auf mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[9193] = { id = 9193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersucht die Amanikatakomben", description = "{class}, wir haben aus zuverlässigen Quellen erfahren, dass die Trolle, die in den Amanikatakomben innerhalb des Sonnenhügels begraben wurden, wieder von den Toten auferstanden sind. Ich möchte, dass Ihr die Katakomben untersucht und dass Ihr alle leblosen Überreste, die Ihr dort auffindet, verbrennt. Die Auferstehung weiterer Kreaturen sollte dadurch verhindert werden.\n\nIhr kommt am schnellsten dorthin, wenn Ihr von der Enklave aus in Richtung Nordwesten reist. So gelangt Ihr in die Nähe des westlichen Eingangs der Katakomben.", sourceObjective = "Untersucht die Amanikatakomben und verbrennt 10 mumifizierte Trollüberreste. Kehrt anschließend zu Waldläuferin Vynna in der Enklave der Weltenwanderer in den Geisterlanden zurück.", progress = "Das ist eine äußerst makabre und würdelose Angelegenheit, {class}. Ich kann Euch doch vertrauen, dass Ihr diesen Auftrag erfüllt?", completion = "Abscheulich, aber glaubt mir, es war notwendig. Ihr habt mit Euren Nachforschungen eine gute Tat vollbracht, {class}. Bitte, nehmt dies als Zeichen unserer Großzügigkeit und Anerkennung an.", sourceObjectiveStatus = "unverified-source-field" }
quests[9194] = { id = 9194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Runenstoffrobe", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-7229:\n\n8 Runenstoffroben.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 8 Runenstoffroben und die Handwerksverfügung für die Runenstoffroben zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
