quests[9198] = { id = 9198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Thoriumröhre", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-558:\n\n14 Thoriumröhren.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 14 Thoriumröhren und die Handwerksverfügung für die Thoriumröhren zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9199] = { id = 9199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolljuju", description = "Die Körper der Trolle, die in den Amanikatakomben begraben wurden, sind wieder von den Toten auferstanden! Ich möchte, dass Ihr dorthin geht und mir einen Beweis für ihren endgültigen Tod bringt. Manche dieser Trollmumien, sowie ihre lebendigen Artgenossen, tragen Juju bei sich. Es handelt sich dabei um leuchtende Objekte, denen eine unbekannte Macht innewohnt. Wahrscheinlich ist es das, was sie am Leben erhält!\n\nDie Katakomben liegen im Sonnenhügel, direkt Richtung Osten. Man sagte mir, dass der einfachste Weg hinein an der Nordwand des Hügels liegt. Seht Euch dort um, {class}!", sourceObjective = "Sammelt 8 Trolljuju und bringt sie zu Apotheker Venustus in der Enklave der Weltenwanderer in den Geisterlanden.", progress = "Ich muss Euch wohl nicht erst sagen, dass wir uns diesen Ärger mit den von den Toten auferstandenen Trollen hier bei uns kaum leisten können! Wir haben schon genug Probleme mit der Todesfestung im Süden!", completion = "Mumien, die von den Trollpriestern wiedererweckt werden... clever! Die Waldschattentrolle wollen ihre Reihen wohl mithilfe nekromantischer Mittel verstärken. Ich wette, dass diese Orakel das Juju bei ihrem Wiedererweckungsritual verwendet haben.\n\nIhr habt Eure Pflicht wieder einmal so erfüllt, wie es sich für jemanden mit ständig wachsendem Ansehen geziemt. Nehmt diesen Lohn als Dank.", sourceObjectiveStatus = "unverified-source-field" }
