quests[9206] = { id = 9206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Zitteraal", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer FS-9:\n\n30 Zitteraale.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 30 Zitteraale und die Handwerksverfügung für die Zitteraale zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9207] = { id = 9207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grubenlichterzproben", description = "Ich wurde vom Sanktum der Sonne hierher geschickt, um ein paar Erzproben zu sammeln, aber die Gnolle haben diesen Ort überrannt! Mein Kopf wird noch auf dem Präsentierteller landen, wenn ich diese Proben nicht bald zum Magister bringe. Vielleicht könnt Ihr mir helfen, {class}?\n\nIhr findet das Erz in den Zinn- und Kupfervorkommen, aber auch die Gnolle tragen es mit sich herum. Sobald Ihr genug habt, bringt Ihr es zu Magister Quallestis beim Sanktum der Sonne, direkt östlich von hier. Überquert die Todesschneise, das Sanktum liegt genau südlich vom Sonnenhügel.", sourceObjective = "Sammelt 6 Einheiten Grubenlichterz und bringt sie zu Magister Quallestis beim Sanktum der Sonne in den Geisterlanden.", progress = "Wie kann ich Euch helfen, {class}?", completion = "Mein Lehrling konnte sich nicht selbst um diese Angelegenheit kümmern? Ich werde noch ein Wörtchen mit ihr zu reden haben, sobald sie wieder da ist, Gnolle hin oder her. Außerdem, warum ist sie nicht mit Euch zurückgekommen?\n\n<Der Magister seufzt.>\n\nSie ist eine schwierige Persönlichkeit und ihre Ausbildung wird mir noch helle Freude bereiten. Danke, dass Ihr mir diese Proben gebracht habt, {class}. Wir hoffen ein paar spezielle Eigenschaften darin zu entdecken, die uns im Kampf gegen die Geißel von Nutzen sein können.\n\nBitte nehmt diesen Lohn als Zeichen meiner Wertschätzung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9208] = { id = 9208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Greuelwächter - Arkanum des Schutzes", description = "Zanza kann viele antike Trollverzauberungen mit den richtigen Komponenten herstellen! Habt Ihr von dem Greuelwächter gehört? Nein, natürlich nicht. Euer Geist wurde mit jämmerlicher Elfenmagie verwirrt.\n\nBringt mir ein Arkanum, wie es die Elfen herstellen, damit ich das Böse zerstören kann. Seid Ihr erfolgreich, so soll der Greuelwächter Euch gehören.", sourceObjective = "Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum des Schutzes.", sourceObjectiveStatus = "unverified-source-field" }
quests[9209] = { id = 9209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Greuelwächter - Arkanum der Schnelligkeit", description = "Zanza kann viele antike Trollverzauberungen mit den richtigen Komponenten herstellen! Habt Ihr von dem Greuelwächter gehört? Nein, natürlich nicht. Euer Geist wurde mit jämmerlicher Elfenmagie verwirrt.\n\nBringt mir ein Arkanum, wie es die Elfen herstellen, damit ich das Böse zerstören kann. Seid Ihr erfolgreich, so soll der Greuelwächter Euch gehören.", sourceObjective = "Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum der Schnelligkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[9210] = { id = 9210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Greuelwächter - Arkanum des Fokus", description = "Zanza kann viele antike Trollverzauberungen mit den richtigen Komponenten herstellen! Habt Ihr von dem Greuelwächter gehört? Nein, natürlich nicht. Euer Geist wurde mit jämmerlicher Elfenmagie verwirrt.\n\nBringt mir ein Arkanum, wie es die Elfen herstellen, damit ich das Böse zerstören kann. Seid Ihr erfolgreich, so soll der Greuelwächter Euch gehören.", sourceObjective = "Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum des Fokus.", sourceObjectiveStatus = "unverified-source-field" }
quests[9211] = { id = 9211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eiswächter", description = "Ah, der Eiswächter. Es ist ein leichter Hauch schützender Magie, der bestimmte Teile der Ausrüstung bedeckt. Der Eiswächter verleiht jenen, die gegen Kreaturen von Frost und Eis kämpfen, erhöhten Schutz vor deren Angriffen.\n\nWie bei allem anderen auch, das vom Zornwirker hergestellt wird, so hat auch dieses Stück seinen Preis - einen Preis, der nicht diskutiert werden kann, wie viel Ihr Euch auch beklagen mögt. Interesse?", sourceObjective = "Mataus der Zornwirker bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 10 Insignien des Kreuzzugs und 30 Gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[9212] = { id = 9212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus den Katakomben", description = "Sehe ich so verängstigt aus, wie ich mich fühle? Diese Trolle haben mich aus dem Hinterhalt überfallen und in diesem Käfig gefangen gehalten. Ich glaube, sie wollen mich opfern! Helft mir von hier zu fliehen!\n\nDas Schloss des Käfigs ist nicht allzu kompliziert... Ich kann es von dieser Seite nur nicht erreichen. Befreit mich und geleitet mich zurück zur Enklave der Weltenwanderer. Ich bin mir sicher, dass Hauptmann Helios Euch dafür entlohnen wird, außerdem wäre ich Euch für immer dankbar!", sourceObjective = "Begleitet Waldläuferin Lilatha zu Hauptmann Helios bei der Enklave der Weltenwanderer in den Geisterlanden.", completion = "Ihr seid ein ziemlicher Held, {class}, sie da lebend herausbekommen zu haben. Ich denke, wir müssen einen Gegenschlag planen, um diese Katakomben auszuräuchern. Als wenn wir nicht schon genug Ärger mit den lebenden Trollen hätten!\n\nIhr habt heute außerordentlich gute Arbeit geleistet, Ihr verdient eine Belohnung. Sucht Euch etwas aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[9213] = { id = 9213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schattenwächter", description = "Das Machwerk eines Genies! Wie beim Eiswächter, ist es auch beim Schattenwächter ein leichter Hauch schützender Magie, der bestimmte Teile der Ausrüstung bedeckt. Der Schattenwächter wird Euch genauso wie der Eiswächter einen guten Batzen Geld kosten.\n\n<Mataus streckt seine Hand aus und reibt seine Finger aneinander.>\n\nInteresse?", sourceObjective = "Mataus der Zornwirker bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 10 Insignien des Kreuzzugs und 30 Gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[9214] = { id = 9214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Arsenal der Waldschattentrolle", description = "{class}, ich möchte, dass Ihr so viele Waldschattentrolle wie möglich erledigt. Wir müssen ihre Reihen so weit wie möglich ausdünnen, bevor wir uns der Todesfestung zuwenden können. Und wenn Ihr schon mal dabei seid, sollten wir gleich zwei Fliegen mit einer Klappe schlagen! Bringt einfach sämtliche Waffen mit, die Ihr bei den Trollen findet. Es wäre eine Verschwendung sie zusammen mit den Trollen verrotten zu lassen und wir könnten sie im Kampf gegen die Geißel einsetzen.\n\nErledigt ihre Lager im Osten und Süden bei Zeb'Tela und Zeb'Nowa.", sourceObjective = "Sammelt 3 Kopfjägeräxte, 3 Schattenzauberstreitkolben, 3 Klauen eines Pantherlords und 3 Verhexerstäbe. Bringt sie zu Hauptmann Helios bei der Enklave der Weltenwanderer in den Geisterlanden.", progress = "Habt Ihr die Waffen beschafft? Sobald wir die Reihen der Waldschattentrolle dezimiert haben, können wir uns wieder dem Kampf gegen die Geißel widmen.", completion = "Ich werde umgehend einige Waldläufer entsenden, um den Schaden, den Ihr unter den Waldschattentrollen angerichtet habt, zu begutachten. Wenn die von Euch mitgebrachte Waffensammlung auch nur ansatzweise den Erfolg Eures Angriffs gegen die Trolle widerspiegelt, sollten wir mit den Überlebenden leichtes Spiel haben. Das wird uns einen baldigen Angriff auf die Geißel ermöglichen.\n\nHier, nehmt diese Münze als Zeichen meiner Dankbarkeit, das schafft wieder etwas Platz in meinem Geldbeutel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9215] = { id = 9215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir Kel'gashs Kopf!", description = "GESUCHT: Bringt den Kopf von Kel'gash dem Boshaften, Häuptling der Waldschattentrolle, zu Hauptmann Helios. Die Wahl der Mittel steht frei. Kel'gash soll sich irgendwo im Süden, in Zeb'Nowa, herumtreiben.\n\n\n\nBELOHNUNG: Ja, aber nicht im Voraus!", sourceObjective = "Bringt den Kopf von Kel'gash dem Boshaften zu Hauptmann Helios bei der Enklave der Weltenwanderer in den Geisterlanden.", progress = "Was ist das für ein widerlicher Gestank?", completion = "Ah, Kel'gashs Kopf ist der Quell dieses wundervollen Aromas. Ihr habt offensichtlich ganze Arbeit geleistet, {class}!\n\nDer Tod ihres Anführers hat die Waldschattentrolle ins Chaos gestürzt. Berücksichtigt man jetzt noch Eure letzten Einsätze zur Dezimierung ihrer Anzahl, denke ich, dass jetzt der Zeitpunkt für unsere Gegenoffensive gekommen ist, um sie ein für alle Mal zu vernichten.\n\nIhr habt meinen Dank, {name}. Kann ich Euch vielleicht für einen dieser Gegenstände begeistern?", sourceObjectiveStatus = "unverified-source-field" }
quests[9216] = { id = 9216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faulende Herzen", description = "Ich habe gehört, dass die Amanitrolle die Herzen ihrer Feinde essen, um deren Stärke zu stehlen. Sie könnten etwas im Schilde führen, {name}. Bereitet man sie richtig auf, kann man aus den Herzen der Untoten mächtige Elixiere gewinnen.\n\nJagt die Zombies in der Todesschneise und bringt mir ihre Herzen. Ich werde Euch die Art von Verstärkung zeigen, die wir Euren körperlichen Fähigkeiten im Kampf gegen die Untoten verleihen können.", sourceObjective = "Bringt 10 faulende Herzen zu Magistrix Aminel in Tristessa.", progress = "Habt Ihr die Zombieherzen, nach denen ich verlangt habe, {name}?", completion = "Nehmt dieses Gebräu, {name}. Sobald Ihr es getrunken habt, erfährt Eure körperliche Stärke im Kampf gegen die Geißel einen Schub. Wenn Ihr noch mehr von dieser Probe brauchen solltet, bringt mir mehr Herzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9217] = { id = 9217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr faulende Herzen", progress = "Habt Ihr mir noch mehr Zombieherzen gebracht? Ich kann so viele davon verarbeiten, wie Ihr mir besorgen könnt, {name}.", completion = "Dies wird Euch mit mehr Stärke im Kampf gegen die Geißel versorgen. Bringt mir mehr Herzen, falls Ihr welche findet, {name}." }
quests[9218] = { id = 9218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wirbelknochenstaub", description = "Die dunklen Energien, welche durch die Körper reanimierter Skelette fließen, reichern sich hauptsächlich in ihrer Wirbelsäule an. Ich habe eine Methode entdeckt, dank der man diese Energie in einen Trank mischen kann, der unsere magischen Fähigkeiten im Kampf gegen die Untoten verstärkt.\n\nBringt mir ein paar Einheiten Wirbelknochenstaub und ich werde Euch gerne eine Probe von dem Trank abgeben. Ihr könnt zahlreiche Skelette in der Todesschneise finden, westlich von hier.", sourceObjective = "Bringt 10 Einheiten Wirbelknochenstaub zu Magistrix Aminel in Tristessa.", progress = "Habt Ihr die Proben, nach denen ich verlangt habe, {name}?", completion = "Hier, für Euch, {name}. Ihr werdet den Unterschied sofort spüren!\n\nIhr könnt mir jederzeit mehr Wirbelknochenstaub bringen, ich kann so viel davon verarbeiten, wie Ihr mir besorgen könnt. Nebenwirkungen? Naja, Eure Stimme klingt ein bisschen höher, aber das sind lediglich die Rückstände des Staubs, die verrückt spielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9219] = { id = 9219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Wirbelknochenstaub", progress = "Ihr habt noch mehr Wirbelknochenstaub auftreiben können? Ich kann so viele davon verarbeiten, wie Ihr mir besorgen könnt.", completion = "Dieser Wirbelknochenstaub ist nach wie vor mächtig, {name}. Bringt mir auch weiterhin welchen, wenn Ihr Verstärkung für Eure magischen Fähigkeiten im Kampf gegen die Geißel benötigt." }
quests[9220] = { id = 9220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg gegen die Todesfestung", description = "Wenn Ihr unserer Sache dienen wollt, gibt es keinen besseren Ort und keinen idealeren Zeitpunkt, als das Hier und Jetzt.\n\nMit dem Wiederaufbau des Sanktums der Sonne haben wir das Banner des Widerstandes im Angesicht der Thronfeste unseres Feindes gehisst, kurz vor den Toren der Todesfestung.\n\nGeht und tötet die Horden der Untoten, die diesen finsteren Hort der Geißel bewohnen.", sourceObjective = "Tötet in der Todesfestung 5 Augen von Dar'khan, 6 nerubische Zenturio und 6 Wehklagende und kehrt anschließend zu Magister Idonis beim Sanktum der Sonne in den Geisterlanden zurück.", completion = "Die Geißel hat unsere Rache zu spüren bekommen, {name}. Nicht mehr lange und ihre verfluchte Zitadelle wird in Trümmern liegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9221] = { id = 9221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überragende Kampfausrüstung - Freund der Dämmerung", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen freundlichen Ruf genießt, muss sich bei Käufen mit einem hohen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", sourceObjective = "Für 30 Insignien der Dämmerung und 30 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9222] = { id = 9222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epische Kampfausrüstung - Freund der Dämmerung", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen freundlichen Ruf genießt, muss sich bei Käufen mit einem extrem hohen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", sourceObjective = "Für 110 Insignien der Dämmerung und 110 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9223] = { id = 9223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überragende Kampfausrüstung - Wohlwollen der Dämmerung", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen wohlwollenden Ruf genießt, muss sich bei Käufen mit einem ziemlich unerschwinglichen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", sourceObjective = "Für 20 Insignien der Dämmerung und 20 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9224] = { id = 9224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epische Kampfausrüstung - Wohlwollen der Dämmerung", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen wohlwollenden Ruf genießt, muss sich bei Käufen mit einem extrem unerschwinglichen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", sourceObjective = "Für 75 Insignien der Dämmerung und 75 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9225] = { id = 9225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epische Kampfausrüstung - Respekt der Dämmerung", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen respektvollen Ruf genießt, muss für epische Gegenstände noch immer einen sehr hohen Preis bezahlen. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", sourceObjective = "Für 45 Insignien der Dämmerung und 45 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9226] = { id = 9226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überragende Kampfausrüstung - Respekt der Dämmerung", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen respektvollen Ruf genießt, kann Gegenstände zu einem recht angemessenem Preis erwerben. Ich würde Euch zu einem Geschäft raten!", sourceObjective = "Für 7 Insignien der Dämmerung und 7 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9227] = { id = 9227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überragende Kampfausrüstung - Ehrfurcht der Dämmerung", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen ehrfürchtigen Ruf genießt, erhält bei Käufen einen Preisnachlass. Ich würde Euch zu einem Geschäft raten!", sourceObjective = "Für 6 Insignien der Dämmerung und 6 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9228] = { id = 9228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epische Kampfausrüstung - Ehrfurcht der Dämmerung", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen ehrfürchtigen Ruf genießt, erhält bei Käufen garantiert den besten Preisnachlass. Ich würde Euch zu einem Geschäft raten.", sourceObjective = "Für 27 Insignien der Dämmerung und 27 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9229] = { id = 9229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramaladnis Schicksal", description = "Ramaladni war ein Krieger der Bruderschaft; er war ein Schüler von Hochlord Mograine bevor die Dämmerung überhaupt existierte! Als ihn die Nachricht von Mograines Tod erreichte, wurde er von Wut und Hass überwältigt.\n\nVersteht bitte, {name}, wenn Wut und der Drang nach Vergeltung von jemandem Besitz ergreifen, hört er auf, ein Mensch zu sein, und wird stattdessen zur Verkörperung der Emotionen, die ihn beherrschen. Und so geschah es, dass Ramaladni, beseelt vom Geist der Vergeltung, Naxxramas betrat um Rache zu üben... und niemals zurückkehrte.\n\nBetretet Naxxramas und findet heraus, was mit Ramaladni geschah.", sourceObjective = "Betretet Naxxramas und bringt Ramaladnis Schicksal in Erfahrung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9230] = { id = 9230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramaladnis eisiger Griff", description = "Den Ring wiederherzustellen, scheint eine ziemliche Herausforderung zu sein, {name}. Seht ihr, er wurde hergestellt aus Runen, die sich in Bauwerken der Geißel finden - in Bauwerken wie Naxxramas. Es könnten noch weitere Materialien gebraucht werden, aber Eure Hauptsorge sollte es sein, diese gefrorenen Runen zu beschaffen. Ich kann dem Ring seinen alten Glanz zurückgeben, wenn ihr mir bringt, was ich dazu benötige.", sourceObjective = "Korfax in der Kapelle des Hoffnungsvollen Lichtes möchte, dass Ihr ihm 1 gefrorene Rune, 1 blauen Saphir und 1 Arkanitbarren bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9231] = { id = 9231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse" }
quests[9232] = { id = 9232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Einzige, das ich kann...", description = "Ihr haltet Euch für einen Helden der Dämmerung, ja? Ich habe gesehen, wie unsere besten Soldaten von Kel'Thuzads Gefolgsleuten überrannt wurden. Wie könnte jemand, der so ahnungslos ist wie Ihr, in Naxxramas bestehen?\n\n<Wilhelm seufzt.>\n\nPah, was für eine Wahl habe ich denn? Ihr seid das Beste, das ich zur Verfügung habe; warum sollte ich Euch nicht helfen?\n\nOmarion hat mir einen Plan hinterlassen. Es ist das Einzige, das ich kann... Ich kann ein paar Varianten dieser Hosen herstellen, Ihr müsst mich nur mit den Materialien versorgen.", sourceObjective = "Handwerker Wilhelm in der Kapelle des Hoffnungsvollen Lichts möchte, dass Ihr ihm 2 gefrorene Runen, 2 Essenzen des Wassers, 2 blaue Saphire und 30 Goldstücke bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9233] = { id = 9233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omarions Leitfaden", description = "Wilhelm,\n\nsolltet Ihr das hier lesen, bin ich bereits tot - endlich. Ihr sollt wissen, dass meine letzten Gedanken vor dem Tod Euch und Eurer Unfähigkeit als Handwerker galten. Unglücklicherweise besitzt der Überbringer dieses Leitfadens noch weniger Geschick als Ihr.\n\nZu dem Buch: Es beinhaltet meine letzten Anleitungen. Fertigt dem Überbringer dieses Leitfadens an, was immer dieser wünschen mag. Ich bin mir sicher, dass Ihr ein saftiges Honorar für Eure Dienste verlangen werdet, denn im Grunde seid Ihr nun mal ein Gauner.\n\nVerachtungsvoll,\n\nOmarion", sourceObjective = "Bringt Omarions Leitfaden zu Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9234] = { id = 9234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisfluchstulpen", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, Eisfluchstulpen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.", sourceObjective = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 5 gefrorene Runen, 12 Thoriumbarren, 2 Arkanitbarren, 2 Essenzen des Wassers und 200 Gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[9235] = { id = 9235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisflucharmschienen", description = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, Eisflucharmschienen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.", sourceObjective = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 4 gefrorene Runen, 12 Thoriumbarren, 2 Arkanitbarren, 2 Essenzen des Wassers und 200 Gold.", sourceObjectiveStatus = "unverified-source-field" }
