quests[9245] = { id = 9245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisschuppenstulpen", description = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, Eisschuppenstulpen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.", sourceObjective = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 5 gefrorene Runen, 16 schwere Skorpidschuppen, 5 Essenzen des Wassers, 3 geschmeidige unverwüstliche Bälge und 200 Gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[9246] = { id = 9246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisschuppenbrustplatte", description = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, eine Eisschuppenbrustplatte herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.", sourceObjective = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 8 gefrorene Runen, 24 schwere Skorpidschuppen, 7 Essenzen des Wassers, 5 geschmeidige unverwüstliche Bälge und 300 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9247] = { id = 9247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Bewahrers", description = "{name},\n\nIn der Vergangenheit habt Ihr die Interessen der Argentumdämmerung nach bestem Gewissen und Können gewahrt. In einer Zeit der größten Not, ertönt wieder einmal der Ruf zu den Waffen.\n\n{name}, solltet Ihr uns unterstützen wollen, meldet Euch bitte bei dem Bewahrer der Schriften an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjective = "Bringt den Brief vom Bewahrer der Schriften zu ihm, in die Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9248] = { id = 9248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bescheidene Darbringung", description = "Ishnu-alah, {race}. Bringt mir den Beweis für den Tod eines Lords des Abyssischen Rates und ich werde Euch mit einem Gegenstand entlohnen, der Euch bei Euren Kämpfen gegen die Qiraji von großem Nutzen sein wird.", sourceObjective = "Aurel Goldblatt auf Burg Cenarius in Silithus möchte, dass Ihr ihr 1 abyssisches Szepter bringt. Euer Ruf bei dem Zirkel des Cenarius muss außerdem wohlwollend sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9249] = { id = 9249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "40 Lose - Bauplan: Dampfpanzersteuerung" }
quests[9250] = { id = 9250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundstab von Atiesh", description = "Mit dem Grundstab ist bereits der wichtigste Teil von Atiesh vervollständigt worden. Es fehlen lediglich noch Stabkopf und -fuß. Außerdem gibt es noch ein kleineres Problem bezüglich des Stabs und seiner Rolle hinsichtlich Sargeras' Lenkung zum Bösen.\n\nFindet jemanden, der Euch beim Aufspüren der noch fehlenden Teile und beim Austreiben alles Verderbten aus dem Hohestab zur Seite steht.", sourceObjective = "Findet jemanden, der Euch dabei hilft, die letzten beiden Teile des Stabs zu finden und das Böse daraus zu vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9251] = { id = 9251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, der korrumpierte Hohestab", description = "Ihr fragt Euch, warum Ihr noch immer am Leben seid? Schließlich haltet Ihr einen Gegenstand in Euren Händen, der vom Bösen erfüllt ist. Die Antwort ist nicht eindeutig, {name}. Ich tue nur, was ich tun muss.\n\nKel'Thuzad sitzt auf seinem Thron hoch oben in Naxxramas, konspiriert... Er sucht was Ihr besitzt und besitzt was Ihr sucht.\n\nWas den Stabfuß angeht, er wurde von dem Zwerg, Brann Bronzebart, gehalten, als er Ahn'Qiraj betrat. Er hat Ahn'Qiraj zwar verlassen, den Stabfuß von Atiesh jedoch zurückgelassen.\n\nSolltet Ihr beim Wiedererlangen der Stücke Erfolg haben, kehrt mit ihnen zu mir zurück.", sourceObjective = "Anachronos in den Höhlen der Zeit in Tanaris möchte den Stabkopf und -fuß von Atiesh.", sourceObjectiveStatus = "unverified-source-field" }
quests[9252] = { id = 9252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Morgenluft", description = "Die Zahl der Angriffe durch Truppen der Geißel hat merklich zugenommen, {name}. Unsere Verteidigung hält gerade noch so stand und Verstärkung aus Silbermond ist nicht in Sicht. Reicht uns eine helfende Hand und unterstützt uns bei der Verteidigung des Dorfes. Zieht aus und erledigt einige der Untoten, die durch die Todesschneise wandeln.", sourceObjective = "Tötet 4 Moderknochenmarodeure und 4 dunkle Gespenster. Kehrt anschließend zu Waldläuferin Sareyn in Morgenluft im Immersangwald zurück.", completion = "Vielen Dank, {name}. Es ist eine undankbare Aufgabe, der wir hier nachgehen, doch Eure heutige Mithilfe hat sie ein wenig einfacher gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9253] = { id = 9253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenwächter Deryan", description = "Die zunehmenden Angriffe der Geißel lassen mich vermuten, dass einer der schützenden Runensteine an der Grenze zu den Geisterlanden eine Fehlfunktion erlitten hat.\n\nWir nutzten diese uralten Runensteine, um uns vor den Untoten zu beschützen. Die meisten wurden jedoch zerstört oder gingen nach dem Angriff auf den Sonnenbrunnen verloren.\n\nFolgt der Straße nach Süden, in Richtung der Geisterlande, und sucht auf der westlichen Seite nach einem kleinen Pfad. Ihr findet Runenwächter Deryan bei einem der nahegelegenen Runensteine; er wird wissen, ob etwas schief gelaufen ist.", sourceObjective = "Sprecht mit Runenwächter Deryan im Immersangwald nahe der Grenze zu den Geisterlanden.", completion = "Jemand aus Morgenluft muss Euch zu mir geschickt haben. Ich wusste doch, dass es nur eine Frage der Zeit war, bevor Hilfe eintrifft.", sourceObjectiveStatus = "unverified-source-field" }
quests[9254] = { id = 9254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der eigensinnige Lehrling", description = "Vielen Dank für Eure Hilfe, {name}. Während ich versuchen werde, hier wieder für Ordnung zu sorgen, möchte ich Euch um einen Gefallen bitten. Eine meiner ehemaligen Lehrlinge hat sich aufgemacht, um sehr gefährlichen Untersuchungen nachzugehen. Sie reiste zum Sanktum des Ostens, inmitten der Todesschneise.\n\nIch sorge mich um ihr Wohlergehen. Bitte versucht sie zu finden und bringt sie wieder zur Vernunft.", sourceObjective = "Sprecht mit Lehrling Mirveda beim Sanktum des Ostens im Immersangwald.", completion = "Es rührt mich, dass meine ehemalige Mentorin nach mir sehen lässt. Es ist nur traurig, dass sie seit langer Zeit kein Vertrauen mehr in meine Arbeit hat.\n\nIhr verschwendet Eure Zeit, Ihr könnt mich nicht überreden zu ihr zurückzugehen. Entweder helft Ihr mir mit meinen Untersuchungen hier oder Ihr geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9255] = { id = 9255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschungsnotizen", description = "Wie entmutigend meine Forschungsergebnisse auch sein mögen, so enthalten sie doch wertvolle Informationen. Ein Magister muss sich meine Arbeit ansehen, bevor wir ernsthaft etwas unternehmen. Bitte, nehmt diese Notizen zu Magistrix Landra Morgenwandler in Morgenluft, westlich von hier.", sourceObjective = "Bringt die Forschungsnotizen zu Magistrix Landra Morgenwandler in Morgenluft im Immersangwald.", progress = "Habt Ihr etwas für mich?", completion = "Diese Notizen... es ist schockierend. Wenn das stimmt, dann ist der Schaden, den das Land entlang der Todesschneise erlitten hat, nicht wiedergutzumachen.\n\nIch werde dem Großmagister sofort Bescheid sagen. Ein weiterer Grund für unser Volk, dieser Welt zu entfliehen und sein wahres Schicksal in der Scherbenwelt zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9256] = { id = 9256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenluft", description = "Ich habe noch eine Aufgabe für Euch, {name}. Waldläufer Degolien wurde nach Morgenluft entsandt, um mehr über einen Angriff getriebener Blutelfen auf eine nahegelegene Werft herauszufinden. Er hat um Verstärkung gebeten, die wir ihm leider noch nicht geben können. Sucht ihn auf und unterstützt ihn so gut Ihr könnt.\n\nIhr kommt nach Morgenluft, indem Ihr der Straße folgt, die vom Falkenplatz hinaus Richtung Süden führt. Viel Glück, {name}.", sourceObjective = "Sprecht mit Waldläufer Degolien in Morgenluft im Immersangwald.", completion = "Danke, dass Ihr gekommen seid, {name}. Es steht um einiges schlechter, als wir angenommen hatten. Die Getriebenen haben den Ankerplatz der Sonnensegel bereits gänzlich eingenommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9257] = { id = 9257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Hohestab des Wächters", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, {name}. Ihr seid einem Alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert und kehrt zu mir zurück.", sourceObjective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9258] = { id = 9258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Versengte Hain", description = "Ein fauler Moder der Verderbnis, welcher die Erde durchzieht, geht der Ausbreitung der Geißel voraus. Daher haben wir schützende Runensteine entlang der Grenze zu den Geisterlanden erbaut, die das Land gegen diese Seuche beschützen sollen.\n\nDer westlichste Runenstein wurde während eines Angriffs der Geißel zerstört, was uns dazu zwang, das umgebende Gebiet vollständig niederzubrennen, um die weitere Ausbreitung der Verderbnis aufzuhalten.\n\nMeine Schwester, Larianna Flusswind, bewacht den Versengten Hain. Geht und findet sie; möglicherweise hat sie Arbeit für Euch.", sourceObjective = "Findet Larianna Flusswind nahe des Versengten Hains, südwestlich des Immersangwalds.", completion = "Ah, mein Bruder hat Euch geschickt. Es gibt da etwas, wobei ich Eure Hilfe gebrauchen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[9259] = { id = 9259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrat am Blutsegel" }
quests[9260] = { id = 9260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erforscht die Geißel von Sturmwind", description = "Der Lichkönig hat seine untoten Diener hierher geschickt - sie stehen also sozusagen direkt vor unserer Haustüre. Wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Sturmwind gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren leuchtende Energie dieselbe ist wie diejenige, welche die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Lichtet die Reihen dieser entarteten Kreaturen, wenn Ihr schon einmal dabei seid, und bringt mir neben Eurem Bericht auch etwas als Beweis dafür, dass sie tot sind. Ihr werdet nicht leer ausgehen. Geht jetzt!", sourceObjective = "Beschafft Euch drei dunkle nekrotische Steine von den Dienern der Geißel außerhalb von Sturmwind und untersucht die leuchtenden Runenkreise in der Nähe ihres Lagers.", sourceObjectiveStatus = "unverified-source-field" }
