quests[9266] = { id = 9266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedergutmachung" }
quests[9267] = { id = 9267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilen alter Wunden", progress = "Überlegt es Euch lieber zweimal, bevor Ihr Ratschet betretet, {name}! Die Kunde von Euren schlechten Taten hat sich bereits verbreitet.\n\nIhr habt jedoch Glück, soeben ist ein Schiff eingetroffen, das viele Verwundete aus einem Kampf mit den Blutsegelbukanieren transportiert. Dies ist Eure letzte Chance, zu beweisen, dass Ihr kein totaler Schuft seid. Helft uns, indem Ihr uns Leinenstoff für Verbände und leere Phiolen für Tränke bringt.", completion = "Ich bin froh, dass Ihr Eure Fehler eingesehen habt, {name}. Sorgt weiter für Nachschub; so leicht werden wir Eure Taten nicht vergessen!" }
quests[9268] = { id = 9268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg zur See", progress = "Ihr wollt also wieder Freunde werden mit den Goblins von Tanaris, {name}? Wir benötigen Rohstoffe für Segel und Kanonen, um unsere alten Feinde, die Blutsegelbukaniere, zu bekämpfen. Bringt mir Magiestoff und starken Fluxus, und wir werden darüber nachdenken, Eure Untaten zu vergeben.", completion = "Sorgt weiter für Nachschub, {name}. Wir Goblins vergessen nicht so schnell!" }
quests[9269] = { id = 9269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Hohestab des Wächters", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, {name}. Ihr seid einem Alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert und kehrt zu mir zurück.", sourceObjective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9270] = { id = 9270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Hohestab des Wächters", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, {name}. Ihr seid einem Alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert und kehrt zu mir zurück.", sourceObjective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9271] = { id = 9271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Hohestab des Wächters", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, {name}. Ihr seid einem Alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert und kehrt zu mir zurück.", sourceObjective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9272] = { id = 9272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleider machen Seebären", sourceObjective = "Harrr... wenn Ihr scharf 'drauf seid, Euch an der Gesellschaft von uns erfahrenen Seebären zu erfreuen, dann zieht Euch auch besser an wie ein richtiger Lump! Hier, streift 'n passenden Fetz'n über, bevor ich Euch kielholen lasse.\n\nEuch steht das Zeug sicher besser als es Rotauge Ben, dem alten Seebär, je gepasst hat. Hab' ihn bei 'nem höllischen Sturm auf See verloren.\n\nTragt's mit Stolz, Kumpel!", sourceObjectiveStatus = "unverified-source-field" }
quests[9273] = { id = 9273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "iCoke-Gewinngutschein einlösen" }
quests[9274] = { id = 9274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister der Ertrunkenen", description = "Der See im Norden wird seit langer Zeit von den Geistern meiner Ahnen heimgesucht, {name}. Die armen Seelen waren Opfer eines tragischen Unfalls, bei dem etliche von ihnen am Grund des Sees ertranken.\n\nDie Ursache dieser Geschehnisse ist längst in Vergessenheit geraten, aber ihre quälenden Schreie erinnern noch heute an ihren Fluch.\n\nFalls Ihr dazu bereit seid, möchte ich, dass Ihr zum See geht und ihrem Leiden ein Ende bereitet, {name}. Ich wäre Euch dankbar dafür, und sie auch, da bin ich sicher.", sourceObjective = "Waldläufer Krenn'an aus der Enklave der Weltenwanderer möchte, dass Ihr beim nahegelegenen See 8 rachsüchtige Erscheinungen und 8 ruhelose Erscheinungen tötet.", completion = "Ich bin dankbar für Eure Hilfe, {name}. Es schmerzt mich, die Geister meiner Ahnen in diesem jämmerlichen Zustand zu sehen. Mögen sie in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9275] = { id = 9275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Würze liegt der Tod", description = "Ich wurde von den Weltenwanderern angeheuert, um ihnen bei der Lösung ihres Trollproblems behilflich zu sein. Ich denke, dass ich die Antwort auf ihr Problem parat habe.\n\nIch verfüge über eine Reihe hochwirksamer Gifte. Trolle sind lebende Wesen wie Ihr und ich, und müssen daher regelmäßig Nahrung zu sich nehmen. Wenn wir also etwas Gift unter ihr Essen mischen... nun, das Resultat dürfte sehr unterhaltsam sein!\n\nSicherlich möchtet Ihr uns zur Hand gehen, um uns die Waldschattentrolle südlich von hier, in Zeb'Nowa, vom Hals zu schaffen? Das Lager erstreckt sich über die ganze nördliche und südliche Seite der Straße nach Zul'Aman.", sourceObjective = "Vergiftet die Trollnahrungsvorräte in den Lagern von Zeb'Nowa. Kehrt anschließend zu Apotheker Venustus bei der Enklave der Weltenwanderer in den Geisterlanden zurück.", completion = "Ah, hervorragend! Ich wusste es, ein {race} war die richtige Wahl, um das Gift hinreichend zu verteilen. Mit etwas Glück werden die Waldschattentrolle schön fett, bevor sie durch die Wirkung des Gifts in den Nether eingehen. Damit dürften die Weltenwanderer ihre Ruhe haben und ich kann endlich meine wohlverdiente Heimreise nach Tristessa antreten.\n\nEs war mir eine Freude mit Euch zu arbeiten, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9276] = { id = 9276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Zeb'Tela", description = "Unsere Ressourcen hier sind recht begrenzt, {class}, daher ist Eure Hilfe für uns unverzichtbar. Ich wurde vom Hauptmann damit beauftragt, die regelmäßigen Störangriffe auf die Lager der Waldschattentrolle zu überwachen. Wir versuchen die Trolle so lange zu beschäftigen, bis wir genug Kräfte für eine vernichtende Offensive zusammenziehen können, um sie endgültig auszulöschen.\n\nBis dahin benötigen wir jeden Freiwilligen, der uns dabei helfen kann, die Anzahl der Waldschattentrolle zu reduzieren.\n\nDenkt Ihr, Ihr könntet nach Osten in Richtung Zeb'Tela reisen und ihnen ein wenig Schaden zufügen?", sourceObjective = "Tötet 8 Schattenzauberer der Waldschattentrolle und 8 Kopfjäger der Waldschattentrolle. Kehrt anschließend zu Weltenwanderin Solanna bei der Enklave der Weltenwanderer in den Geisterlanden zurück.", completion = "Gut, sehr gut! Das habt Ihr hervorragend gemeistert! Dann wollen wir doch mal sehen, ob Ihr auch der nächsten Herausforderung gewachsen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[9277] = { id = 9277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Zeb'Nowa", description = "Es ist Zeit für eine größere Herausforderung. Zeb'Nowa, südlich von hier, beherbergt die mächtigsten Waldschattentrolle. In unserem Bestreben, die Anzahl der Trolle so klein wie möglich zu halten, erteile ich Euch den Auftrag, dorthin zu gehen und alle Euch zur Verfügung stehenden Mittel einzusetzen, um den Trollen so viel wie möglich zuzusetzen.\n\nKann ich auf Euch zählen, {name}? Seid Ihr bereit für die Trolljagd?", sourceObjective = "Tötet 10 Pantherlords der Waldschattentrolle und 10 Verhexer der Waldschattentrolle. Kehrt anschließend zu Weltenwanderin Solanna bei der Enklave der Weltenwanderer in den Geisterlanden zurück.", completion = "Unglaublich! Ihr solltet Euch unbedingt mit unserem Hauptmann über einen Beitritt in die Reihen der Weltenwanderer unterhalten.\n\nNun gut, {name}, Ihr habt uns die dringende Atempause zum Sammeln unserer Streitkräfte verschafft. Genau genommen scheinen unserer letzten Zählung nach nur wenige Trolle übrig zu sein! Vielleicht können wir uns nun mit den Streitkräften Tristessas vereinen, um gemeinsam die Todesfestung anzugreifen, anstatt unsere Zeit weiter mit den hiesigen Trollen zu verschwenden.\n\nIch denke, Ihr habt Euch eine kleine Belohnung verdient. Greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[9278] = { id = 9278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Jaeleil in der Azurwacht einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt den Geschenkgutschein der Azurwacht zu Jaeleil in der Azurwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9279] = { id = 9279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr habt überlebt!", description = "Kümmert Euch nicht um meine Wunden, <Bruder/Schwester>. Es ist ein Wunder, dass überhaupt jemand von uns überlebt hat!\n\nIch dachte schon, Ihr wärt nicht durchgekommen; Ihr wurdet seit Wochen vermisst!\n\nEs ist etwas passiert und die Exodar ist abgestürzt. Viele ließen ihr Leben.\n\nEs ist ein Segen, dass Ihr noch unter uns weilt, {name}! Mit Euch an unserer Seite werden wir bald wieder in Sicherheit sein! Proenitus hat mich beauftragt, Euch zu ihm zu schicken, sobald Ihr erwacht seid. Er wartet außerhalb des Schiffes, südwestlich am Fuße des Hügels auf Euch.", sourceObjective = "Sprecht mit Proenitus bei der Absturzstelle im Am'mental.", completion = "{name}, bei meiner ewigen Seele, es ist gut, Euch zu sehen! Ich weiß nicht, warum die Exodar abgestürzt ist. Nur diejenigen von uns, die in diesem Teil des Schiffs waren, sind noch am Leben.\n\nUns bleibt nicht viel Zeit, wenn wir so viele wie möglich retten wollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9280] = { id = 9280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederaufladen der Heilkristalle", description = "Unsere dringlichste Sorge ist die Erschöpfung unserer Heilkristalle. Wir müssen sie so schnell wie möglich wieder aufladen!\n\nUnglücklicherweise können wir das derzeit nur, indem wir das Blut der einheimischen Talmotten abzapfen. Ihr Blut eignet sich als Ersatzstoff.\n\nMan findet die Motten entlang des gesamten Tals, jedoch verstärkt im Nordwesten.", sourceObjective = "Beschafft Euch 6 Phiolen mit Mottenblut von den in der Nähe hausenden Talmotten und bringt sie zu Proenitus bei der Absturzstelle im Am'mental.", progress = "{name}, habt Ihr schon das benötigte Mottenblut für die Heilkristalle? Überlebende sind über das gesamte Tal verstreut und die Zeit drängt!", completion = "Wie bedauernswert, dass diese Kreaturen sterben mussten, damit wir überleben können - wahlloses Töten entspricht nicht dem Weg der {race}. Wie auch immer, das von Euch gesammelte Blut wird unsere Heilkristalle wieder aufladen, somit war ihr Opfer nicht umsonst.", sourceObjectiveStatus = "unverified-source-field" }
quests[9281] = { id = 9281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg frei machen", description = "Magister Kaendris hat mich entsandt, um die Gegend von aggressiven Wildtieren zu säubern. Sobald die Gegend sicher ist, wollen die Magister hier einen Außenposten gegen die Geißel errichten.\n\nWenn Ich als Lehrling eines gelernt habe, dann ist das, Verantwortung zu delegieren, besonders bei solch lebensgefährlichen Unternehmungen!\n\nWenn Ihr Interesse habt, werde ich Euch gut dafür bezahlen, die Großen Spindelweber und Geisterklauenverheerer westlich und südlich von hier aus dem Weg zu räumen.", sourceObjective = "Lehrling Vor'el von Andiliens Grund in den Geisterlanden möchte, dass Ihr 10 Große Spindelweber und 10 Geisterklauenverheerer tötet.", completion = "Vielen Dank für Eure Unterstützung, {name}. Mir schaudert bei dem Gedanken, mich so nahe bei der Todesfestung in den Wald zu wagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9282] = { id = 9282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Enklave der Weltenwanderer", description = "Die Magister und die Weltenwanderer mögen nicht immer einer Meinung sein, {name}, doch wenn es um Dar'Khan geht, stimmen alle überein, dass wir gemeinsam einen Weg finden müssen, um ihn und seine Legionen zu besiegen.\n\nWaldläuferin Vynna, in der Enklave der Weltenwanderer im Nordosten, ist auf einige wichtige Informationen über unseren Feind gestoßen. Sucht sie auf und seht, ob sie Eure Hilfe benötigt.", sourceObjective = "Magister Kaendris beim Sanktum der Sonne möchte, dass Ihr mit Waldläuferin Vynna bei der Enklave der Weltenwanderer in den Geisterlanden sprecht.", completion = "Kaendris hat Euch geschickt? Möglicherweise habe ich eine Aufgabe für Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9283] = { id = 9283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Überlebenden!", description = "Jetzt haben wir wieder genügend Heilkristalle, aber sie sind nicht der einzige Weg, wie wir den Verletzten helfen können. Alle Draenei können die Gabe der Naaru einsetzen, um zu heilen. Ihr müsst den Überlebenden des Absturzes mit dieser Gabe helfen.\n\nDie meisten Überlebenden findet Ihr im Westen und Nordwesten, aber der Absturz hat uns alle im gesamten Tal verstreut.\n\nDie Überlebenden haben sehr unter der Strahlung der Energiekristalle gelitten, daher solltet Ihr sie an dem roten Schein, der sie umgibt, erkennen können.\n\nIhr müsst uns helfen, sie zu retten, {name}!", sourceObjective = "Wendet Eure Gabe der Naaru an, um einen der Überlebenden der Draenei zu heilen, die über das ganze Am'mental verstreut sind. Kehrt dann zu Zalduun bei der Absturzstelle im Am'mental zurück.", completion = "Dem Licht sei Dank! Ihr habt getan, was nur ein wahrer Held vollbringen kann, {name}! Jeder {race}, den Ihr gerettet habt, verdankt Eurer Selbstlosigkeit sein Leben!\n\nBitte, nehmt diesen Vorratsbeutel. Ihr könnt ihn sicher besser gebrauchen als ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[9284] = { id = 9284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aldor Faction Test" }
