quests[9291] = { id = 9291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Priester" }
quests[9292] = { id = 9292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesprungener nekrotischer Kristall", description = "Ihr entdeckt beim Körper der toten Monstrosität einen gesprungenen Kristall, der langsam mit nekrotischer Energie pulsiert.", sourceObjective = "Bringt den gesprungenen nekrotischen Kristall zu Leutnant Orrin außerhalb der Tore von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[9293] = { id = 9293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was getan werden muss...", description = "Der nahegelegene See wurde von einem Energiekristall des Schiffs verseucht. Zahlreiche Pflanzen und Tiere des Am'mentals sind deswegen mutiert.\n\nIch habe bereits eine Theorie aufgestellt, wie man den See heilen kann, allerdings brauche ich Proben von mutierten Wurzelpeitschern für eine Auswertung. Man findet sie im Westen der Am'menfelder.\n\nWerdet Ihr mir helfen, {class}?", sourceObjective = "Sammelt 10 Peitscherproben ein und bringt sie zu Botanikerin Taerix bei der Absturzstelle im Am'mental.", progress = "Der Zustand aller Proben muss einwandfrei sein, damit wir eine Chance haben, den See zu entseuchen.\n\nUns bleibt nicht viel Zeit, {class}!", completion = "Genau das habe ich gebraucht. Danke, {class}!\n\nWährend Ihr unterwegs wart, habe ich bereits meine Ausrüstung aufgebaut, um die Proben auswerten zu können. Ich sollte lediglich ein paar Augenblicke benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9294] = { id = 9294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heilung des Sees", description = "Dem Licht sei Dank, ich glaube, es wird funktionieren! Ich habe einen Wirkstoff, den Ihr beim Silberwellensee im Süden einsetzen müsst. Er wird den Effekt des strahlenden Energiekristalls des Schiffs, der hier heruntergestürzt ist, neutralisieren.\n\nSchwimmt raus auf den See und verwendet dort den Neutralisierungswirkstoff. Keine Sorge, Ihr werdet der Strahlung nicht lange genug ausgesetzt sein, um verseucht zu werden.", sourceObjective = "Verwendet den Neutralisierungswirkstoff bei dem strahlenden Energiekristall und kehrt anschließend zu Botanikerin Taerix bei der Absturzstelle im Am'mental zurück.", completion = "Euren Schilderungen zufolge hat der Neutralisierungswirkstoff funktioniert! Ich wünschte nur, ich wüsste, wie lange er anhält. Wir müssen den Energiekristall gänzlich aus dem See entfernen.\n\nDanke, {name}! Ich werde Tedon bitten, den Neutralisierungswirkstoff sofort an einem der gefangenen Tiere auszuprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[9295] = { id = 9295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brief von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt den zerfledderten Brief zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9296] = { id = 9296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse", description = "Der Stein strahlt eine dunkle Energie aus. Bringt ihn zu einer bestimmten Person.", sourceObjective = "Bringt den dunklen nekrotischen Stein zu einer bestimmten Person.", sourceObjectiveStatus = "unverified-source-field" }
quests[9297] = { id = 9297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse", description = "Der Stein strahlt eine dunkle Energie aus. Bringt ihn zu einer bestimmten Person.", sourceObjective = "Bringt den dunklen nekrotischen Stein zu einer bestimmten Person.", sourceObjectiveStatus = "unverified-source-field" }
quests[9298] = { id = 9298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse", description = "Der Stein strahlt eine dunkle Energie aus. Bringt ihn zu einer bestimmten Person.", sourceObjective = "Bringt den dunklen nekrotischen Stein zu einer bestimmten Person.", sourceObjectiveStatus = "unverified-source-field" }
quests[9299] = { id = 9299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notiz von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt die verblichene Notiz zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9300] = { id = 9300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt die zerfranste Seite zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9301] = { id = 9301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umschlag von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt den blutbefleckten Umschlag zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9302] = { id = 9302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreiben von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt das zerknitterte Schreiben zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9303] = { id = 9303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immunisierung", description = "Zhanaa braucht unsere Hilfe, um Teile aus der Exodar zu bergen. Taerix hat eine Immunisierungsmethode vorbereitet, mit der die Nisteleulkins behandelt werden können. Sie bewohnen die Gegend, in der die meisten Teile gefunden werden können.\n\nNähert Euch den noch nicht verseuchten Biestern und wendet den Kristall auf sie an. Die anderen müsst Ihr leider umbringen. Ihr findet sie im Nisteldickicht und bei den Nistelhügeln im Südosten.", sourceObjective = "Wendet den Immunisierungskristall auf 6 Nisteleulkin an. Kehrt anschließend zu Verteidiger Aldar bei der Absturzstelle im Am'mental zurück.", progress = "Je mehr wir tun können, um den Nistelwald aufzuräumen, desto schneller kann Zhanaa zurück an die Arbeit.", completion = "Da jetzt viele der Eulkin immunisiert wurden, können wir uns auf unseren Aufbruch von hier konzentrieren, ohne die gesamte Eulkinpopulation ausrotten zu müssen.\n\nHier, sucht Euch etwas aus. Ihr habt eine so wunderbare Arbeit geleistet, Ihr verdient eine Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[9304] = { id = 9304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokument von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt das verschmierte Dokument zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9305] = { id = 9305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzteile", description = "Wir konnten einen beschädigten holografischen Emitter nach dem Absturz bergen. Sollten wir ihn reparieren können, besteht die Möglichkeit, dass wir noch andere Überlebende außerhalb des Am'mentals finden.\n\nVon dem Schiff hätte man einige Apparaturen sichern können, die geeignete Ersatzteile geliefert hätten, aber die heimischen Eulkin haben sie verschleppt, bevor wir sie überhaupt erreichen konnten.\n\n{name}, Ihr müsst ins Nisteldickicht und in die Nistelhügel im Süden gehen und die Ersatzteile zurückholen!", sourceObjective = "Beschafft 4 Emitterersatzteile und kehrt anschließend zu Technikerin Zhanaa bei der Absturzstelle im Am'mental zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9306] = { id = 9306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Verteidiger Aldar", description = "{name}, Verteidiger Aldar hat sich nach jemandem umgesehen, der sich um unser Problem, das wir wegen der mutierten Eulkin im Nisteldickicht haben, kümmert. Es gilt den bedauerlichen Nebeneffekt unserer unbeabsichtigten Landung hier in den Griff zu bekommen.\n\nIhr findet ihn draußen im Süden bei der Absturzstelle. Bitte, sprecht mit ihm so bald Ihr könnt.", sourceObjective = "Sprecht mit Verteidiger Aldar bei der Absturzstelle im Am'mental.", sourceObjectiveStatus = "unverified-source-field" }
quests[9307] = { id = 9307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitleid", description = "Der nahegelegene Silberwellensee wurde durch ein Teil des Schiffs, das in ihn stürzte, verseucht. Daraufhin sind die meisten Lebewesen in der Umgebung mutiert, manche wurden sogar feindselig. Am schlimmsten sind die mutierten Eulkin.\n\nGeht nach Süden ins Nisteldickicht und tötet so viele dieser bemitleidenswerten Kreaturen, wie Ihr könnt. Es ist eine traurige Aufgabe, {class}, bitte macht es schnell und schmerzlos.", sourceObjective = "Tötet 14 mutierte Eulkin und kehrt anschließend zu Verteidiger Aldar bei der Absturzstelle im Am'mental zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9308] = { id = 9308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überreste eines Blutelfen?", description = "Ihr vermutet, dass der tote Blutelf, dessen Überreste Ihr hier auf dem Boden liegend gefunden habt, den Sin'dorei angehörte. Wie es aussieht, fiel er den wilden Klauen von mehreren mutierten Eulkin im Dickicht zum Opfer.\n\nBeim Durchsuchen des Leichnams entdeckt Ihr ein Amulett, das an einer Kette um seinen Hals hängt. Vielleicht ist es für Verteidiger Aldar von Interesse?", sourceObjective = "Bringt das Blutelfenamulett zu Verteidiger Aldar bei der Absturzstelle im Am'mental.", sourceObjectiveStatus = "unverified-source-field" }
quests[9309] = { id = 9309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Späher", description = "Verschiedene Quellen konnten uns nun bestätigen, dass beim Schattenkamm ungewöhnliche Dinge vor sich gehen.\n\nDas ist äußerst beunruhigend, denn wir dachten, dass die bisherigen Aufklärungsmissionen gründlich genug gewesen wären. Einer meiner Späher hat sich noch nicht zurückgemeldet.\n\n{class}, Ihr müsst für mich Richtung Südwesten gehen, zur anderen Uferseite des Silberwellensees, und Tolaan finden. Findet heraus, was ihn aufgehalten hat.", sourceObjective = "Sprecht mit Tolaan im Schattenkamm im Am'mental.", completion = "Hilfe... Blutelfen! Ein... ein Hinterhalt. Ich habe... nicht mehr lange...", sourceObjectiveStatus = "unverified-source-field" }
quests[9310] = { id = 9310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwacher nekrotischer Kristall", description = "Ihr findet beim Körper der toten Kreatur einen Kristall, der schwache nekrotische Energie ausstrahlt.", sourceObjective = "Bringt den schwachen nekrotischen Kristall zu Leutnant Rukag im Hof von Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9311] = { id = 9311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutelfenspionage", description = "Ich habe einen Plan. Wir müssen ihren Anführer umbringen. Vielleicht ziehen sie sich ohne ihren Meister zurück, um sich neu zu formieren. Wir müssen Zeit schinden, damit wir die Reparaturen abschließen können.\n\nVerteidiger Aldar muss davon erfahren. Tötet die Gutachterin und kehrt dann zu ihm zurück, um ihn zu erzählen, was wir herausgefunden haben.", sourceObjective = "Tötet Gutachterin Kandress und informiert anschließend Verteidiger Aldar bei der Absturzstelle im Am'mental über die Ereignisse.", completion = "Danke, dass Ihr Euch um die Gutachterin gekümmert habt. Sie war ganz sicher ihre Anführerin. Ich versichere Euch, dass wir uns um den restlichen Haufen, der sich eventuell noch hier in der Nähe aufhält, kümmern werden.\n\nBitte, nehmt eine dieser Waffen als Zeichen unserer Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[9312] = { id = 9312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Emitter", description = "{name}, während Ihr den Schattenkamm erkundet habt, hat Zhanaa weiter am holografischen Emitter gearbeitet. Vielleicht solltet Ihr mit ihr sprechen.", sourceObjective = "Sprecht mit Technikerin Zhanaa bei der Absturzstelle im Am'mental.", completion = "Ja, ja! Ich glaube, ich habe den Emitter reparieren können! Hier, ich muss lediglich den letzten Kristall aktivieren und das sollte es gewesen sein.\n\nSeht, {name}, der Emitter. Er scheint zu funktionieren... es erscheint jemand!", sourceObjectiveStatus = "unverified-source-field" }
quests[9313] = { id = 9313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zur Azurwacht", description = "So weit, so gut, {name}, Ihr müsst allerdings sofort zur Azurwacht reisen und mit Dyvuun sprechen!\n\nEs gibt einen Pfad, der westlich von dieser winzigen Insel führt. Folgt ihm und überquert den Kristallfluss, um auf den größeren Teil der Insel zu gelangen. Wenn Ihr dem Pfad noch weiter folgt, solltet Ihr die Azurwacht finden.\n\nVielleicht könnt Ihr sie ja überzeugen, uns etwas Hilfe und Vorräte zukommen zu lassen. Wir kommen nach, sobald wir können.\n\nIch danke Euch, ohne Euch hätten wir das nicht geschafft!", sourceObjective = "Sprecht mit Techniker Dyvuun bei der Azurwacht auf der Azurmythosinsel.", completion = "Ah, es ist gut, Euch wiederzusehen! Ich bin froh, dass wir beide unsere Emitter reparieren konnten, sonst hätten wir uns wohl nie gefunden. Sorgt Euch nicht, wir werden natürlich Hilfe und Vorräte ins Am'mental schicken.\n\nDa wir gerade von Hilfe sprechen... jetzt wo Ihr hier seid, könnt Ihr Euch ja mal umsehen und Euch bei den anderen vorstellen. Ich weiß, dass es jede Menge zu tun gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9314] = { id = 9314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht von der Azurwacht", description = "{class}! Ein paar dieser mutierten Biester haben mich angesprungen und jetzt ist mein Bein verletzt.\n\nNachdem wir von Zhanaa gehört hatten, wurde ich von der Azurwacht auf eine Spähmission geschickt. Könntet Ihr vielleicht an meiner statt mit Versorgerin Chellan sprechen? Sie muss wissen, wie viele Leute sie in der Azurwacht erwarten soll. Ihr müsst lediglich den Kristallfluss hier überqueren und dem Pfad bis zur Azurwacht folgen.\n\nVergesst nicht, nach einer Unterkunft zu fragen, wenn Ihr dort seid.", sourceObjective = "Sprecht mit Versorgerin Chellan bei der Azurwacht auf der Azurmythosinsel.", completion = "Oh, Ihr müsst einer der Überlebenden sein, von denen wir gehört haben!\n\nIch bin froh, dass Ihr gekommen seid. Keine Sorge, wir schicken jemanden los, der sich Aeuns verletztes Bein ansehen wird.\n\nIch will unbedingt alles über Eure aufregende Überlebensgeschichte hören! Wenn Ihr bis hierhergekommen seid, müsst Ihr sehr tapfer sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9315] = { id = 9315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anok'suten", description = "Kommt näher, ich... ich sterbe.\n\nMan entsandte mich hierher, um... um die Neruber zu besiegen, doch Vandril konnte nicht ahnen, dass sie... sie eine Anführerin haben.\n\n<Der sterbende Blutelf spuckt etwas Blut.>\n\nIhr müsst Anok'suten finden und... und töten. Sie wandert in der Umgebung von... Sonnenkuppe umher.", sourceObjective = "Tötet Anok'suten und kehrt anschließend zu Arkanist Vandril in Tristessa in den Geisterlanden zurück.", completion = "Ich muss mich für die schlechte Aufklärung entschuldigen, {class}. Hätte ich vorher etwas von der Existenz dieser Anok'suten gewusst, hätte ich Euch natürlich umgehend davon in Kenntnis gesetzt.\n\nUnsere Kräfte sind einfach zu weit verteilt und manche Dinge schlüpfen uns unter diesen Umständen einfach durchs Netz.", sourceObjectiveStatus = "unverified-source-field" }
quests[9316] = { id = 9316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Goblins", description = "<Brianna schaut Euch prüfend an.>\n\nIhr wollt also ein paar Goblins töten, was? Nun, wenn Ihr dazu bereit seid, könnt Ihr mit den Wilden in der Nähe anfangen. Bringt mir ihre Zähne als Beweis Eurer Taten.", sourceObjective = "Brianna Schneider auf der Designerinsel möchte, dass Ihr ihr 10 Goblinzähne bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9317] = { id = 9317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geweihte Wetzsteine" }
quests[9318] = { id = 9318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesegnetes Zauberöl" }
quests[9319] = { id = 9319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht im Dunkeln", description = "Wir sind nicht die Einzigen, die dieses Fest feiern, {name}. Die Flamme ist ein wichtiger Bestandteil aller Lebewesen, aller Kulturen. Selbst an den dunkelsten Orten beginnen die Feuer zu leuchten.\n\nWenn Ihr dergleichen sehen möchtet, so wagt Euch in die Tiefe. Sucht nach den Freudenfeuern in Stratholme, Scholomance, bei den Ogern des Düsterbruchs und in den Hallen der Schwarzfelsspitze selbst. Ich erwarte Eure Rückkehr.", sourceObjective = "Findet und berührt die Freudenfeuer innerhalb der Schwarzfelsspitze, dem Düsterbruch, Scholomance und Stratholme. Kehrt dann zum Flammenbewahrer zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9320] = { id = 9320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstklassiger Manatrank" }
quests[9321] = { id = 9321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstklassiger Heiltrank" }
quests[9322] = { id = 9322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glühende Feuer in Kalimdor", description = "Die Freudenfeuer des Sonnenwendfests werden überall in Azeroth gefeiert, die mannigfaltigen Länder Kalimdors sind dabei keine Ausnahme. Ihr scheint mir tauglich für eine Reise - wie wäre es mit einem Ausflug?\n\nDas Sonnenwendfest ist erst dann ein Ereignis, wenn man die blau glühenden Feuer in der Welt gesehen hat. Die Feiernden haben Feuer im eisigen Westen von Winterquell, im Nordosten von Azshara, in der Nähe der Heldenwacht in Silithus und beim Eingang zum üppigen Krater von Un'Goro entzündet. Kehrt zu mir zurück, sobald Ihr die Reise beendet habt.", sourceObjective = "Sucht die Lager des Sonnenwendfests in Azshara, Silithus, dem Krater von Un'Goro und Winterquell auf. Kehrt dann zum Flammenbewahrer zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9323] = { id = 9323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glühende Feuer in den Östlichen Königreichen", description = "Das Fest der Flamme ist im ganzen Land verbreitet, {class}. Kein Ort bleibt von der Wärme dieses Ereignisses unberührt, und die prächtigsten Feuer lodern in einem strahlenden Blau. Sucht nach ihnen.\n\nEines befindet sich genau nördlich von der Schwarzfelsspitze. Die anderen liegen tief im Innern der Östlichen Pestländer, in der Nähe eines verfallenen Dorfes; entlang der Straße, die zu den Klippen im bergigen Hinterland führt, und auf dem Weg zu dem Dunklen Portal in den Verwüsteten Landen.\n\nKehrt anschließend zu mir zurück.", sourceObjective = "Reist zu den Lagern des Sonnenwendfests in den Verwüsteten Landen, den Östlichen Pestländern, dem Hinterland und der Sengenden Schlucht. Kehrt dann zum Flammenbewahrer zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9324] = { id = 9324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Orgrimmar", description = "Die Flamme, die aus dem Zentrum von Orgrimmar entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Orgrimmar zum Meister der Lehren.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Was ist das? Sollte ich mich nicht täuschen, so wurde diese Flamme aus dem Herzen Orgrimmars entwendet! Die sengende Hitze spiegelt die kämpferischen Herzen der Orcs und Trolle wider. Was für ein Gewinn für unsere Sammlung! Wie mutig Ihr doch seid - sich in den Bau des Feindes einzuschleichen, um die heilige Flamme zu erlangen!\n\nIch frage mich, welch' Mächte sich in den anderen Städten versteckt halten...", sourceObjectiveStatus = "unverified-source-field" }
quests[9325] = { id = 9325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Donnerfels", description = "Die Flamme, die dem Schamanen von Donnerfels entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Donnerfels zum Meister der Lehren.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Sollte mich meine Vermutung nicht täuschen, so wurde diese Flamme aus Donnerfels entwendet! Die Macht der Geister ist deutlich hörbar! Ihr seid ganz schön gerissen, {name}. Nehmt dies als gerechte Anerkennung Eures Könnens. Hm, hätten wir doch auch alle vier Flammen von den anderen Städten...", sourceObjectiveStatus = "unverified-source-field" }
quests[9326] = { id = 9326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Unterstadt", description = "Die Flamme, die aus den Ruinen über Unterstadt entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Unterstadt zum Meister der Lehren.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Hm... was für ein seltsames Feuer! Es flackert schwach, ist fast nur noch ein Glühen, aber die Hitze ist stark. Ihr sagt, dass Ihr es aus Unterstadt entwendet habt? Faszinierend. Wer weiß, was wir mit den Flammen aller vier Städte erreichen könnten?", sourceObjectiveStatus = "unverified-source-field" }
quests[9327] = { id = 9327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verlassenen", description = "Ich weiß, es mag seltsam erscheinen, aber die Verlassenen sind hier, um uns zu helfen. Ihr solltet mit Hochexekutor Mavren sprechen. Er befindet sich in dem Turm im Westen der Stadt.\n\nWenn Ihr mit ihm gesprochen habt, kehrt bitte zu mir zurück, es gibt da eine schlimme Angelegenheit, bei der ich dringend Eure Unterstützung benötige.", sourceObjective = "Sprecht mit Hochexekutor Mavren in Tristessa in den Geisterlanden.", completion = "Ich weiß, wir Verlassenen mögen in Euren Augen monströs erscheinen, aber ich versichere Euch, wir sind für Euer Volk keine Bedrohung. Wir sind hier, weil wir einen gemeinsamen Feind haben: Dar'Khan den Verräter! Er ist zurückgekehrt und befehligt die Geißel von der Todesfestung im Süden aus.\n\nUnsere Anführerin, Fürstin Sylvanas Windläufer, stammt aus dieser Gegend und war früher eine Elfe. Sie hatte schon mit Dar'Khan zu tun und möchte ihn genauso gern tot sehen, wie Euer Volk.\n\nWir werden ihn zusammen besiegen, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9328] = { id = 9328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Held der Sin'dorei", description = "Dies ist der Beginn eines neuen Zeitalters für unser Volk, {name}. Wir werden unser Land zurückerobern und unseren Bund mit Sylvanas und ihren Verbündeten festigen.\n\nBringt den Kopf des Verräters nach Silbermond, zu Lor'themar Theron, dem Lordregenten Silbermonds. Er wird begierig sein, die Neuigkeit zu erfahren.", sourceObjective = "Bringt Dar'Khans Kopf zu Lor'themar Theron in Silbermond.", progress = "Ihr wünscht eine Audienz bei mir, {class}? Ich kann mich nicht an eine Verabredung erinnern.", completion = "Nun, das ist ein Gesicht, das ich noch nicht so früh hier erwartet hätte.\n\nDas sind ziemlich gute Neuigkeiten, {name}, in mehr Hinsichten, wie Ihr Euch denken könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9329] = { id = 9329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verlassenen", description = "Ich weiß, es mag seltsam erscheinen, aber die Verlassenen sind hier, um uns zu helfen. Ihr solltet mit Hochexekutor Mavren sprechen. Er befindet sich in dem Turm im Westen der Stadt.\n\nWenn Ihr mit ihm gesprochen habt, kehrt bitte zu mir zurück, es gibt da eine schlimme Angelegenheit, bei der ich dringend Eure Unterstützung benötige.", sourceObjective = "Sprecht mit Hochexekutor Mavren in Tristessa in den Geisterlanden.", completion = "Die Verlassenen sind hier, weil wir und die Blutelfen einen gemeinsamen Feind haben: Dar'Khan! Er ist zurückgekehrt und befehligt die Geißel von der Todesfestung im Süden aus.\n\nFürstin Sylvanas Windläufer, die ursprünglich aus dieser Gegend hier stammt, hatte schon früher mit Dar'Khan zu tun und möchte ihn tot sehen!\n\nWir werden ihn besiegen, {name}, und Ihr werdet uns dabei helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9330] = { id = 9330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Sturmwind", description = "Die Flamme, die aus dem Zentrum von Sturmwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Sturmwind zum Geschichtenerzähler.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Also dieses hell leuchtende Feuer... Ihr sagt es kommt aus Sturmwind? Bemerkenswert! Das muss ein ziemliches Abenteuer gewesen sein! Ich werde Euch dafür natürlich entlohnen. Solltet Ihr etwas Ähnliches finden, kommt bitte sofort zu mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[9331] = { id = 9331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Eisenschmiede", description = "Die Flamme, die aus dem Zentrum von Eisenschmiede entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Eisenschmiede zum Geschichtenerzähler.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Diese kraftvolle Flamme muss aus den Hallen von Eisenschmiede stammen; sie ist so unerschütterlich wie die Zwerge selbst. Gut gefangen, {name}. Hätte ich nur die Flammen der anderen Städte... naja, macht Euch nichts draus. Hier ist Euer Lohn.", sourceObjectiveStatus = "unverified-source-field" }
quests[9332] = { id = 9332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Darnassus", description = "Die Flamme, die von der Küste Teldrassils entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Darnassus zum Geschichtenerzähler.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Dieses Feuer ist mit uraltem Kummer erfüllt, {name}. Ihr habt es aus dem Herzen Teldrassils, ja? Unglaublich! Hier, als Anerkennung für Euer Können. Kehrt zu mir zurück, falls Ihr etwas Ähnliches finden solltet - ich könnte Verwendung dafür haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9333] = { id = 9333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handschuhe der Argentumdämmerung" }
quests[9334] = { id = 9334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesegnetes Zauberöl" }
quests[9335] = { id = 9335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geweihte Wetzsteine" }
quests[9336] = { id = 9336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstklassiger Heiltrank" }
quests[9337] = { id = 9337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstklassiger Manatrank" }
quests[9338] = { id = 9338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treue zum Zirkel des Cenarius" }
quests[9339] = { id = 9339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lohn des Diebes" }
quests[9340] = { id = 9340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Große Kluft", description = "Wir stehen kurz davor, vollständig von den Streitkräften der Allianz eingekesselt zu werden. Mit dem ständigen Zustrom von Sin'doreiflüchtlingen aus Azeroth müssen wir einen Weg finden, der vor den neugierigen Blicken des Feindes sicher ist.\n\nIch habe darüber etwas nachgedacht und bin kürzlich zu einer Lösung gekommen. Wir werden eine sichere Passage durch die Große Kluft etablieren.\n\nJa, auch wenn es dort nur so von tödlichen Felsklauen wimmelt, sind sie doch nichts weiter als bloße Tiere, denen wir beibringen können, uns zu fürchten. Ich möchte, dass Ihr loszieht und eine größere Anzahl dieser Biester erlegt. Zeigen wir ihnen, was Angst ist!", sourceObjective = "Waldläuferhauptmann Venn'ren in der Falkenwacht möchte, dass Ihr 8 Steinsichelwelpen und 3 Steinsichelalphas bei der Großen Kluft östlich der Falkenwacht erlegt.", completion = "Gute Arbeit, {name}. Das sollte die Felsklauen lehren, sich von uns fernzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9341] = { id = 9341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenrock der Argentumdämmerung" }
quests[9342] = { id = 9342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plündernde Krustenbohrer", description = "Als ob es nicht schon schlimm genug wäre, dass die Gan'arg in den Minen eingefallen sind, rücken uns nun diese Riesenwürmer von der anderen Seite auf die Pelle!\n\nDa Thrallmars Garnison mit der Verteidigung gegen die Legion und dem Pflegen der Verwundeten beschäftigt ist, bedeutet das, dass ich und die Minenarbeiter uns um dieses Problem kümmern müssen.\n\n<Der Großknecht zeigt auf die schlafenden Peons.>\n\nUnd Ihr sehr ja selbst wie hilfreich sie sind...\n\nIch bezahle Euch gerne ihr Gehalt, wenn Ihr ein paar dieser Würmer vernichtet.", sourceObjective = "Großknecht Razelcraz bei den Minen in der Nähe von Thrallmar möchte, dass Ihr 15 plündernde Krustenbohrer tötet. Die Würmer haben die Angewohnheit, unplötzlich aus ihren unterirdischen Tunneln anzugreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9343] = { id = 9343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenrock der Argentumdämmerung" }
quests[9344] = { id = 9344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der überstürzte Aufbruch", description = "Seid gegrüßt, {name}. Die Scherbenwelt ist ein Ort voller Gefahren, beinahe jedes Mitglied unserer Expedition musste diese leidvolle Erfahrung machen. Ich befürchte, der junge Grelag hat diese Lektion aus erster Hand erfahren.\n\nEr ist ein viel versprechender Schüler, doch es mangelt ihm an Geduld! Er studiert mit Begeisterung die Geschichte seines Volkes und vergisst dabei manchmal die Gefahren des heutigen Lebens.\n\nEr ist zum Rückenbrecherposten aufgebrochen, ohne an die Legion und die Höllenorcs zu denken. Ich habe Angst, dass ihm etwas zugestoßen ist.", sourceObjective = "Scharfseherin Regulkut möchte, dass Ihr ihren Schüler Grelag findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9345] = { id = 9345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herstellung der Salbe", description = "Als ich gerade Zeth'Gor erkennen konnte, wurde ich von einer Patrouille der Legion entdeckt. Ich rannte los in der Hoffnung, dass ich mich in einem der Türme in der Ferne verstecken kann, aber einer ihrer Teufelshunde hat mich eingeholt und mich fast zerfleischt!\n\nIch konnte entkommen, aber mein Bein ist in einem sehr schlechten Zustand. Steingardist Ambelan hat mich gefunden und hierher gebracht.\nJetzt muss ich einen Weg finden, um mein Bein zu versorgen. Wirbelkraut wächst in und um das Tal der Knochen im Norden herum. Eine Salbe daraus wird den Schmerz lange genug betäuben, dass ich weiterreisen kann.", sourceObjective = "Grelag im Rückenbrecherposten möchte, dass Ihr ihm 12 Höllenwirbelkräuter für seine Salbe bringt.", progress = "Habt Ihr die Pflanzen gefunden?", completion = "Die sollten ihren Zweck erfüllen. Ich werde die Salbe fertigstellen und mein Bein schienen, bevor ich nach Thrallmar aufbreche. Wieso glaube ich genau zu wissen, was mir Scharfseherin Regulkut erzählen wird, wenn sie mich so sieht?\n\n<Grelag seufzt halbherzig.>\n\nVielen Dank für Eure Hilfe, {name}. Ich habe noch einige von den Höllenwirbelkräutern übrig. Nehmt sie mit, wenn Ihr sie braucht. Wer weiß, wofür sie noch gut sind?", sourceObjectiveStatus = "unverified-source-field" }
quests[9346] = { id = 9346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Hölleneber fliegen", description = "Habt Ihr schon mal einen fliegenden Hölleneber gesehen? Die brauchen nicht mal Flügel!\n\n<Wachtkommandant Krunk lacht schallend.>\n\nDer Kampf gegen die Lager der Legion im Norden hat unsere Vorräte restlos erschöpft, einschließlich der Katapultmunition. Also der perfekte Augenblick, mal etwas völlig Neues auszuprobieren.\n\nStatt Steine zu verschießen, dachte ich daran, die Kadaver verhungernder Hölleneber in Brand zu stecken, um damit die Lager der Legion zu bombardieren.\n\nMeldet Ihr Euch freiwillig oder muss ich Euch erst dazu zwingen?", sourceObjective = "Wachtkommandant Krunk in Thrallmar möchte, dass Ihr ihm 10 klobige Hölleneberkadaver von verhungernden Höllenebern bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9347] = { id = 9347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Leerwandler", description = "Als Ihr die Essenz eingehender betrachtet, erblickt Ihr bösartig umherwirbelnde Energien, die in einem Gefäß aus einem unbekannten Material eingeschlossen sind. Ihr haltet einen Moment inne und fühlt, wie sich irgendetwas in Eure Gedanken schleicht und Ihr verspürt das Verlangen, näher zu kommen und tiefer in die Essenz zu blicken.\n\nAls Ihr bemerkt, dass Euer Bewusstsein immer mehr abgleitet, wendet Ihr erschrocken Euren Blick ab. Während Ihr überlegt, was Ihr mit Eurem Fund anstellen sollt, bemerkt Ihr am Rande Eures Bewusstseins noch immer die lauernde Gegenwart der Essenz.", sourceObjective = "Bringt die pulsierende Leerwandleressenz zu Mahuram Starkhuf in Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9348] = { id = 9348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felshetzerzusammentrieb", description = "Die Scherbenwelt ist voller faszinierender Lebewesen. Faszinierend und extrem tödlich.\n\nDas Land beherbergt eine große Zahl der unterschiedlichsten Raubtiere. Das erscheint zunächst seltsam für solch ein ödes Land, doch bei genauer Betrachtung haben diese Kreaturen untereinander eine Art Hierarchie entwickelt.\n\nDie Felsklauen haben sich eine weitere tödliche Bestie untertan gemacht, den Felshetzer. Anscheinend züchten und halten sie diese als Jagd- und Wachtiere. Ich muss unbedingt in Erfahrung bringen, mit welchen Methoden sie die Felshetzer abrichten. Dazu müssen wir ihre Brutstätte nahe Terokkar im Südwesten ausräuchern und untersuchen.", sourceObjective = "Tötet 10 gefangene Felshetzerjungtiere und sammelt 12 Felshetzereier für Mahuram Starkhuf in Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9349] = { id = 9349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felshetzereier sammeln", description = "Ich bin am verhungern!\n\nIst das nicht ironisch? Ein verhungernder Koch?\n\n<Legassi lacht halbherzig und tippt auf ein gefaltetes Pergament in seiner Tasche.>\n\nLaut dieser Touristenkarte, der wir gefolgt waren, bevor wir so hinterhältig niedergeschossen wurden, gibt es im Südwesten eine Gegend, nahe bei den Wäldern von Terokkar. Sie wird der Messerdornpfad genannt und angeblich soll es dort von leckeren Felshetzereiern nur so wimmeln!\n\nIch könnte ein tolles Festmahl daraus zaubern, wenn nur jemand mutig genug wäre, dorthin zu gehen und ein paar zu sammeln!", sourceObjective = "Bringt 12 Felshetzereier zu Legassi bei der Zeppelinabsturzstelle auf der Höllenfeuerhalbinsel.", progress = "Habt Ihr die Eier schon?\n\n<Legassis Magen knurrt vor Vorfreude.>", completion = "Für ausgezeichnete Küche braucht man ausgezeichnete Zutaten. Und diese Eier sehen großartig aus!\n\nIch habe gerade meine Pfanne geputzt, Ihr seid also herzlich eingeladen, mir bei einem Mahl Gesellschaft zu leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9350] = { id = 9350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arbeit eines Peons ist nie zu Ende", description = "Die dauernden Angriffe der Legion haben unsere Verteidigung schwer in Mitleidenschaft gezogen. Wenn die Palisaden fallen, fällt auch Thrallmar. Ich habe die Peons beauftragt, den Wall zu verstärken und reparieren, aber uns gehen die Materialien aus.\n\nGrelag, einer der Schüler der Scharfseher, kennt sich gut mit den alten Riten aus und hat vorgeschlagen, auf einen Brauch unserer Vorfahren zurückzugreifen. Vor langer Zeit versorgte die Grollhufjagd uns mit Fleisch, Fellen und Knochen. Wenn wir die Jagd auf die Grollhufe im Südosten wieder aufnehmen, bekommen wir alles, was wir brauchen, und ehren gleichzeitig unsere Vorfahren.", sourceObjective = "Sammelt 8 Grollhufbälge und 8 Grollhufknochen von tobenden Grollhufen. Kehrt zu Wachkommandant Krunk in Thrallmar zurück, wenn Ihr alle Materialien beisammen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9351] = { id = 9351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Leerwandler", description = "Auch wenn ich den Rahmen des Zeppelins repariert bekomme, muss ich einen Ersatztreibstoff finden! Ich habe kein Benzin mehr, und es gibt weit und breit keine Tankstelle!\n\nSüdlich von hier liegt eine Gegend namens Sphärenfelder. Dort wimmelt es nur so von wilden und unkontrollierten Leerwandlern, aber für mich sind sie eher wandelnde Batterien.\n\nWenn Ihr mir genug von Ihrer Essenz bringt, kann ich damit den Motor des Zeppelins zum Laufen bekommen. Ich wette fünf Gold, dass ich dann sogar einen niedrigeren Verbrauch habe!", sourceObjective = "Bringt 10 kondensierte Leerwandleressenzen zu \"Schreihals\" Quack Lufthans bei der Zeppelinabsturzstelle.", progress = "Konntet Ihr die Essenzen besorgen?", completion = "Perfekt! Ich glaube sogar, dass das so gut funktionieren wird, dass ich den Motor umbauen muss, damit ich alle Vorteile dieses Kraftstoffs nutzen kann! Falls - ich meine natürlich - wenn wir hier wegkommen, muss ich allen in Area 52 meine Entwürfe zeigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9352] = { id = 9352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darnassische Eindringlinge", description = "Abgesehen von der konstanten Bedrohung durch die Getriebenen, befasse ich mich auch mit den zahlreichen Berichten über angebliche Nachtelfensichtungen.\n\nObwohl viele dieser Sichtungen frei erfunden sind, gibt es doch einen Vorfall, der weiterer Untersuchungen bedarf. Das Sanktum des Westens, eine unserer primären Energiequellen, hatte eine massive Fehlfunktion und Gerüchte, eine darnassische Sabotageaktion sei der Grund dafür, machen die Runde.\n\nBegebt Euch dorthin und kümmert Euch um jeden, der verdächtig aussieht. Meldet Euch bei Leybewahrerin Velania, sie überwacht das Sanktum.", sourceObjective = "Reist zum Sanktum des Westens südwestlich vom Falkenplatz und vernichtet jegliche Eindringlinge, die Ihr dort findet. Berichtet anschließend Leybewahrerin Velania.", completion = "Nachtelfen? Hier? Diese Ratten!\n\nGlaubt Ihr, es besteht irgendeine Verbindung zu der Fehlfunktion in meinem Sanktum? Falls Ihr irgendwelche Informationen habt, bringt Ihr sie besser umgehend zu Hauptmann Sonnenmal!", sourceObjectiveStatus = "unverified-source-field" }
quests[9353] = { id = 9353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "iCoke-Geschenkgutschein einlösen" }
quests[9354] = { id = 9354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach neuen Materialien", description = "<Der Zwerg schaut erwartungsvoll von seiner Arbeit auf.>\n\nWenn Ihr etwas bestellen wollt, stell Euch hinten an, {class}. Ich habe beide Hände mit der Reparatur der Ausrüstung der Söhne und den Vorbereitungen für den Tag, an dem wir wieder in die Schlacht gegen den Feind ziehen, voll.\n\nSeit die Krustenbohrer in den Minen eingefallen sind, nehmen unsere Metallvorräte stetig ab. Ich habe schon mit natürlichen Materialien von den tobenden Grollhufen, die nordwestlich der Feste grasen, experimentiert. Auch wenn sie kein Ersatz für Eisen sind, kann ich sie gut einsetzen.", sourceObjective = "Sammelt 8 Grollhufbälge und 8 Grollhufsehnen von den tobenden Grollhufen. Wenn Ihr die Materialien habt, bringt sie zu Humphry in der Ehrenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[9355] = { id = 9355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Aufgabe für einen intelligenten Helden", description = "Gut, {class}. Nun, da die Verstärkung anrückt, können wir endlich wieder ein mehr oder weniger normales Leben führen.\n\nEines unserer ersten Ziele ist die Wiederaufnahme des Transports von Männern und Waren auf der Straße nach Südwesten, aber dazu müssen wir sie erst von den Krustenbohrern zurückfordern, die diese Gegend in Beschlag genommen haben.\n\nWenn Ihr uns bei dieser Aufgabe helfen würdet, wären die Söhne Euch sehr dankbar. Gebt auf die aufgewühlte Erde Acht, die sie hinterlassen!", sourceObjective = "Tötet 15 plündernde Krustenbohrer und kehrt dann zu Großknecht Biggums in der Ehrenfeste zurück.", completion = "Gut gemacht, {name}. Wir sollten uns aber nicht zu früh freuen. Ich bin mir sicher, dass wir diese Würmer nicht zum letzten Mal gesehen haben. Wenn sie ihre hässlichen Köpfe wieder in diese Gegend strecken sollten, werden die Söhne sie schon erwarten!", sourceObjectiveStatus = "unverified-source-field" }
quests[9356] = { id = 9356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So weich wie Butter", description = "Quack sagt immer, er fliegt \"so weich wie Butter\". Ich glaube eher, sein Kopf ist so \"weich wie Butter\"!\n\nSchaut Euch nur die Trümmer da drüben an. Er nennt das eine \"harte\" Landung.\n\nKlar, wir wurden beschossen, und ich würde es ihm ja auch nachsehen, wenn er nicht immer so mit seinen Flugkünsten angeben würde!\n\nIch glaube, ich koche ihm ein paar Flügel, um ihm einmal einen Wink mit dem Zaunpfahl zu geben. Im Osten, im Tal der Knochen, findet Ihr Knochenhäuterbussarde. Ihre Flügel sind fleischig, dick und perfekt für meine Zwecke.", sourceObjective = "Bringt 12 fleischige Bussardflügel zu Legassi bei der Zeppelinabsturzstelle.", progress = "Ich kann es kaum erwarten, seinen Gesichtsausdruck zu sehen, wenn er reinhaut! Seit dem Absturz beschwert er sich, dass ich nur ans Essen denke. Nun, jemand muss uns schließlich ernähren, während er am Zeppelin herumschraubt!", completion = "Felshetzereier... Bämm!\n\nHölleneberspeck... Bämm!\n\nBussardflügel... Bämm! Bämm!\n\nWas für ein großartiges Essen. Ihr solltet wirklich mal probieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[9357] = { id = 9357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Aeldon Sonnenmal", description = "Wenn Ihr nach Arbeit sucht, dann sprecht mit Hauptmann Sonnenmal beim inneren Elfentor, geht einfach durch die Türen hinter mir.\n\nLasst mich jetzt in Ruhe, ich muss diesen Halunken verhören.", sourceObjective = "Meldet Euch bei Aeldon Sonnenmal beim inneren Elfentor im Immersangwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[9358] = { id = 9358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waldläuferin Sareyn", description = "Betrachtet die Sicherheit dieses Orts nicht als selbstverständlich. Wir werden von der Geißel im Osten und von den Getriebenen im Westen belagert.\n\nWaldläuferin Sareyn sichert unsere Grenzen vor den Untoten, die uns von der Todesschneise her bedrängen. Folgt der Straße in Richtung Osten und erkundigt Euch, ob sie Unterstützung braucht.", sourceObjective = "Meldet Euch bei Waldläuferin Sareyn außerhalb von Morgenluft im Immersangwald.", completion = "Ihr seid hier, um zu helfen? Warum habt Ihr das nicht gleich gesagt? Wir können jede helfende Hand gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9359] = { id = 9359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuflucht der Weltenwanderer", description = "Ihr habt uns geholfen die Getriebenen wieder unter Kontrolle zu bekommen und dies war von unschätzbarem Wert. Die Weltenwanderer könnten jemanden wie Euch in ihrem Kampf gegen die Amanitrolle gebrauchen.\n\nHaltet nach der Zuflucht der Weltenwanderer nordöstlich von hier Ausschau, sprecht mit Leutnant Dämmerflucht und erkundigt Euch, ob sie Unterstützung braucht.", sourceObjective = "Meldet Euch bei Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer im Immersangwald.", completion = "Ihr seid hier, um zu helfen? Ausgezeichnet!\n\nDer Kampf gegen die Amanitrolle hat uns sehr in Anspruch genommen und fähige Kämpfer wie Ihr sind stets willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9360] = { id = 9360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Amani", description = "Ihr versteht zwar die Sprache dieser Schlachtpläne nicht, aber Ihr könnt klar eine Karte mit den eingetragenen Positionen der Zuflucht der Weltenwanderer und von Morgenluft ausmachen.\n\nAm besten informiert Ihr Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer darüber.", sourceObjective = "Bringt die Angriffspläne der Amani zu Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer.", progress = "Was wollt Ihr mir zeigen?", completion = "Die Trolle haben uns hier festgehalten, während sie einen Angriff auf Morgenluft planten. Wir hatten nichts dergleichen erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9361] = { id = 9361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hölleneber, die etwas andere Delikatesse", description = "Diese Eier sind wundervoll, aber was haltet Ihr davon, wenn wir noch einen Zahn zulegen?\n\nEine Scheibe Speck würde unser Mahl erst richtig abrunden, und ich weiß ganz genau, wo man sie herbekommen könnte.\n\nDieser Ort wimmelt nur so von Höllenebern. Natürlich kann hier niemand das Fleisch überprüfen und weichklopfen, aber wir haben Glück!\n\n<Legassi kramt in seinem Beutel und holt eine Flasche hervor.>\n\nDies wurde zwar nicht gemacht, um es mit Schweinefleisch zu benutzen, aber Improvisation ist alles!", sourceObjective = "Legassi bei der Zeppelinabsturzstelle möchte, dass Ihr 8 Stück geläutertes Hölleneberfleisch sammelt. Um das Fleisch zu reinigen, schüttet die Läuterungsmischung über das besudelte Hölleneberfleisch, das Ihr von den Höllenebern gesammelt habt.", progress = "Habt Ihr das Hölleneberfleisch erfolgreich geläutert?", completion = "Hmmm...\n\nEs sieht essbar aus, wenn man es richtig würzt. Erzählt Quack aber nicht, woraus sein Frühstück besteht, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[9362] = { id = 9362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsherr Krellian", description = "Die Zeit drängt, {name}! Meine Orakelsprüche haben eine mächtige Quelle der Magie offenbart. Ich kann den Turm nicht verlassen und bitte Euch deshalb, diese bösartige Kreatur, die im Besitz dieses Artefakts ist, zu töten.\n\nDer erbärmliche Schwachkopf ist bekannt als Kriegsherr Krellian und versteckt sich hinter seinen Wachen im Tempel von Zin-Malor. Verbrennt ihn zu Asche und nehmt die prismatische Muschel, die er so begehrt, an Euch.", sourceObjective = "Beschafft die prismatische Muschel für Erzmagier Xylem. Der Erzmagier befindet sich in einem Turm auf den Klippen von Azshara.", sourceObjectiveStatus = "unverified-source-field" }
quests[9363] = { id = 9363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnt Morgenluft", description = "Geht nach Morgenluft und klärt Waldläufer Degolien über die Pläne der Amani auf. Morgenluft muss sich auch nach dem Tod von Zul'marosh noch auf einen Angriff der Trolle vorbereiten. Sagt Degolien, dass ich ihm so schnell wie möglich Verstärkung schicken werde.", sourceObjective = "Reist nach Morgenluft im Immersangwald und sprecht mit Waldläufer Degolien.", completion = "Die Informationen, die Ihr mir gebracht habt, sind von entscheidender Bedeutung, {name}. Jetzt, da wir über die Pläne der Trolle Bescheid wissen, können wir uns auf einen Angriff vorbereiten.\n\nSie werden uns nicht ahnungslos überrumpeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[9364] = { id = 9364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespaltene Magie", description = "Meine Untersuchungen haben den einzigartigen Zweck für die prismatische Muschel enthüllt.\n\nGreift die Grollflossen von Azshara mit Verwandlungszaubern an und tragt dabei diese Muschel bei Euch. Wenn Ihr einen Moment wartet, wird die chaotische Aura der Muschel dafür sorgen, dass sie sich für eine kurze Zeit in mehrere kleinere Versionen aufspalten. Tötet diese Kopien so schnell wie möglich, und deren gespaltene Essenzen werden in der Muschel gesammelt.\n\nKehrt zu mir zurück, sobald die Muschel gefüllt ist.Ihr erlernt:", sourceObjective = "Verwandelt die Grollflossen von Azshara und tötet die Kopien, die einige Sekunden später auftauchen. Wenn Ihr 50 verwandelte Kopien vernichtet habt, kehrt zu Erzmagier Xylem in Azshara zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9365] = { id = 9365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lohn des Diebes" }
quests[9366] = { id = 9366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Teufelsblut", description = "Nordöstlich von hier liegen die Teiche von Aggonar. Vor langer Zeit waren sie ein Heiligtum der Draenei, doch fielen sie der Verderbnis anheim, als das Blut des Dämons Aggonar in die heiligen Wasser vergossen wurde.\n\nObwohl es alt und verwässert ist, ist das Blut noch immer von einer enormen Macht erfüllt. Angetrieben durch die puren dämonischen Energien des ursprünglichen Blutes, durchstreifen Terrorbestien dieses Gebiet. Vernichtet sie und sammelt so viel von dem Teufelsblut ein, wie Ihr tragen könnt. Ich werde Euch fürstlich belohnen.", sourceObjective = "Ryathen der Düstere an der Falkenwacht auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 6 Teufelsblutproben von den Terrorbestien bringt, die bei den Teichen von Aggonar umherstreifen.", progress = "Das Teufelsblut... habt Ihr es bekommen, {name}?", completion = "Die in den Proben gespeicherten Energien sind unfassbar stark, {name}. Nun müssen wir nur noch sicherstellen, dass wir auch in Zukunft freien Zugriff auf das Teufelsblut haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9367] = { id = 9367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Fest des Feuers", description = "Die Zeit des Sonnenwendfests ist wieder angebrochen!\n\nJedes Jahr werden, wie die Tradition es verlangt, Flammenbewahrer auserkoren, die die Freudenfeuer in unseren Hauptstädten hüten. Auch wenn Feuer in ganz Azeroth brennen, so müssen unsere stets die heißesten und hellsten von allen sein, um dieser Zeit im Jahr ausreichend Ehrerbietung zu erweisen.\n\nIch hätte da übrigens eine Aufgabe für Euch. Mir ist noch nicht zu Ohren gekommen, ob die Feuer in allen Hauptstädten auch wirklich ordentlich brennen. Reist selbst dorthin und wärmt Euch im Schein der Flammen - überzeugt Euch, dass sie ausreichend heiß sind!", sourceObjective = "Wärmt Euch an den Freudenfeuern in Sturmwind, Eisenschmiede und Darnassus. Sprecht anschließend mit einem Meister der Lehren innerhalb der Hauptstädte.", sourceObjectiveStatus = "unverified-source-field" }
quests[9368] = { id = 9368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Fest des Feuers", description = "Die Zeit des Sonnenwendfests ist wieder angebrochen!\n\nJedes Jahr werden, wie die Tradition es verlangt, Flammenbewahrer auserkoren, die die Freudenfeuer in unseren Hauptstädten hüten. Auch wenn Feuer in ganz Azeroth brennen, so müssen unsere stets die heißesten und hellsten von allen sein, um dieser Zeit im Jahr ausreichend Ehrerbietung zu erweisen.\n\nIch hätte da übrigens eine Aufgabe für Euch. Mir ist noch nicht zu Ohren gekommen, ob die Feuer in allen Hauptstädten auch wirklich ordentlich brennen. Reist selbst dorthin und wärmt Euch im Schein der Flammen - überzeugt Euch, dass sie ausreichend heiß sind!", sourceObjective = "Wärmt Euch an den Freudenfeuern in Orgrimmar, Donnerfels und Unterstadt. Sprecht anschließend mit einem Geschichtenerzähler innerhalb der Hauptstädte.", sourceObjectiveStatus = "unverified-source-field" }
quests[9369] = { id = 9369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederaufladen der Heilkristalle", description = "Wir sind die Draenei. Unser Schiff ist hier abgestürzt und es gibt etliche Verwundete. Unsere dringlichste Sorge ist die Erschöpfung unserer Heilkristalle. Wir müssen sie so schnell wie möglich wieder aufladen!\n\nUnglücklicherweise können wir das derzeit nur, indem wir das Blut der einheimischen Talmotten abzapfen. Ihr Blut eignet sich als Ersatzstoff.\n\nMan findet die Motten entlang des gesamten Tals, jedoch verstärkt im Nordwesten.", sourceObjective = "Beschafft Euch 6 Phiolen mit Mottenblut von den in der Nähe hausenden Talmotten und bringt sie zu Proenitus bei der Absturzstelle im Am'mental.", progress = "Habt Ihr schon das benötigte Mottenblut für die Heilkristalle? Überlebende sind über das gesamte Tal verstreut und die Zeit drängt!", completion = "Wie bedauernswert, dass diese Kreaturen sterben mussten, damit wir überleben können - wahlloses Töten entspricht nicht dem Weg der Draenei. Wie auch immer, das von Euch gesammelte Blut wird unsere Heilkristalle wieder aufladen, somit war ihr Opfer nicht umsonst.", sourceObjectiveStatus = "unverified-source-field" }
quests[9370] = { id = 9370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoppt das Säuberungsritual", description = "Unsere Späher haben kürzlich einen Paladin der Draenei in der Nähe der Teiche von Aggonar aufgegriffen. Wir nehmen an, dass er vorhatte, an einem Säuberungsritual zur Reinigung der Teiche teilzunehmen. Natürlich müssen wir das Vorhaben der Draenei stoppen, oder unsere Teufelsblutquelle wird für immer versiegen.\n\nEr hatte diesen Signalstein bei sich. Offensichtlich hatte er den Auftrag, einen sicheren Ort zu markieren, an dem ein Priester - sie selbst nennen sich 'Anachoret' - in aller Sicherheit ein Säuberungsritual durchführen kann. Nehmt den Stein und platziert ihn am Altar von Aggonar und bereitet einen Hinterhalt für die eintreffenden Draenei vor.\n\nIch schlage vor, dass Ihr besser ein oder zwei Freunde mit Euch bringt.", sourceObjective = "Platziert den Signalstein bei den Teichen von Aggonar am Altar von Aggonar und besiegt alle Anachoreten der Draenei, die auf Eure Signal reagieren. Kehrt anschließend mit dem Signalstein zu Ryathen dem Düsteren bei der Falkenwacht zurück.", progress = "Ihr seid zurückgekehrt, {name}. Habt Ihr dem Aberwitz der Draenei ein Ende gesetzt?", completion = "Das wird diese heiligen Fanatiker lehren, sich um ihren eigenen Kram zu kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9371] = { id = 9371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botanikerin Taerix", description = "{name}, Botanikerin Taerix braucht Eure Hilfe. Bitte, sucht sie bei ihren Lehrlingen außerhalb der Westseite des Schiffes auf.", sourceObjective = "Sprecht mit Botanikerin Taerix bei der Absturzstelle im Am'mental.", completion = "Oh, welch Glück, dass Ihr hier seid! Wir haben einiges zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[9372] = { id = 9372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonische Verderbnis", description = "Willkommen im Posten des Cenarius, {class}. Wir bekommen hier draußen nicht oft Besuch, daher freue ich mich ganz besonders über Eure Anwesenheit. Meine Arbeit mit den Lebewesen dieser trostlosen Umgebung macht es oft erforderlich, alleine in die abgelegensten Winkel zu reisen.\n\nDie Expedition des Cenarius hat mich mit dem Studium einiger der gefährlichsten Tiere der Scherbenwelt beauftragt, und dabei habe ich eine verblüffende Entdeckung gemacht. Obwohl viele Kreaturen bereits massive Veränderungen durchgemacht haben, scheint die Verderbnis noch immer neue Mutationen hervorzurufen. Ich habe mit dem Sammeln von Blutproben begonnen, um diese Veränderungen zu dokumentieren, und dabei ist mir jede Hilfe recht.", sourceObjective = "Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel möchte, dass Ihr 6 Blutproben eines Höllenebers von bulligen Höllenebern sammelt.", progress = "Habt Ihr die Blutproben bekommen?", completion = "Gute Arbeit, {name}. Diese Blutproben werden mir bei meinen Forschungen, und der Expedition bei ihren Studien der Scherbenwelt und ihrer Lebewesen, sehr dienlich sein.\n\nWenn ich den Grund für die fortschreitende Veränderung der Tiere herausfinden könnte, könnte ich vielleicht ein Gegengift herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9373] = { id = 9373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlender Schriftverkehr", description = "Bei der Untersuchung des ramponierten Lederkoffers stellt Ihr fest, dass die Beschädigung des Behälters von der ätzenden Flüssigkeit im Verdauungstrakt des Wurms herrühren muss. Das Leder scheint einst kunstvoll verarbeitet gewesen zu sein, aber die Verzierungen sind nicht mehr deutlich sichtbar.\n\nDas Einzige, was noch zu erkennen ist, ist ein abgenutztes Symbol des Zirkels des Cenarius. Da Ihr nichts über den Inhalt wisst, haltet Ihr es für das Beste, den Koffer zu einem Mitglied des Zirkels zu bringen.", sourceObjective = "Bringt den zerfressenen Lederkoffer zu Thiah Rotmähne in der Nähe der Ruinen von Sha'naar im westlichen Teil der Höllenfeuerhalbinsel.", progress = "Guten Tag, {class}. Was bringt Euch in mein Lager?", completion = "Danke, dass Ihr mir dies hier gebracht habt, {class}. Ich habe mich schon gewundert, warum ich so lange nichts mehr von der Expedition gehört habe. Ich frage mich, wie lange diese Nachricht schon unterwegs ist und was wohl aus ihrem Überbringer geworden ist.\n\nHier habt Ihr etwas Geld für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9374] = { id = 9374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arelions Tagebuch", description = "Mein Mann Arelion war seit unserer Ankunft in der Scherbenwelt von den Teichen von Aggonar fasziniert. Er verbrachte fast seine gesamte Zeit mit dem Studium der heimischen Schleimarten!\n\nVor einigen Tagen verschwand er spurlos. Man sagte mir, dass er tot sei und dass ich nichts mehr für ihn tun könnte.\n\nDoch was ich noch zu tun vermag, ist sicherzustellen, dass seine Forschungen nicht mit ihm gestorben sind. Begebt Euch zu den Teichen im Nordosten und haltet nach den Seiten seines Tagebuchs Ausschau. Er bewahrte sie immer in einem braunen Wanderknappsack auf.", sourceObjective = "Magistrix Carinda bei der Falkenwacht auf der Höllenfeuerhalbinsel möchte, dass Ihr zu den Teichen von Aggonar reist und Arelions Tagebuch sucht.", progress = "Hattet Ihr Glück, {name}? Die Teiche von Aggonar liegen nördlich der Höllenfeuerzitadelle.", completion = "Das Tagebuch meines Ehemanns... hat nicht das Geringste mit seinen Forschungen zu tun!\n\nWie konnte ich nur so blind sein? \"Die magischen Eigenschaften dämonisch beeinflusster Schleimformen\", beinahe hätte ich es geglaubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9375] = { id = 9375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg zur Falkenwacht", description = "<Auf dem geschundenen Gesicht der Blutelfe zeichnet sich bei Eurem Anblick Erleichterung ab.>\n\nBitte, {class}, holt mich aus diesem Käfig heraus! Ich bin der Gruppe aus Thrallmar, trotz Martik Tor'seldoris Warnungen, vorausgereist.\n\nSchreckliche Kreaturen lauerten mir auf. Ich glaube, es waren diese Felshetzer, von denen er immer sprach. Zunächst gelang es mir ihnen zu entkommen, doch das war erst der Anfang meiner Schwierigkeiten.\n\nIch verband gerade meine Wunden, als mich die Vogelmenschen fanden und zurück in ihre Höhle schleiften, wo sie mich in diesen Käfig sperrten! Ich muss unbedingt zur Falkenwacht!", sourceObjective = "Beschützt die verwundete Blutelfenpilgerin auf Ihrem Weg zur Falkenwacht und sprecht dann mit Taleris Morgenblick.", completion = "<Taleris ruft einige der Blutelfen aus dem Außenposten herbei.>\n\nSchafft sie herein und versorgt ihre Wunden!\n\n<Taleris wendet sich wieder Euch zu.>\n\nSie kann sich glücklich schätzen, dass Ihr sie noch rechtzeitig gefunden habt, {class}. Viel länger hätte sie dort draußen alleine nicht überlebt.\n\nKonntet Ihr verstehen, was sie gesagt hat?", sourceObjectiveStatus = "unverified-source-field" }
quests[9376] = { id = 9376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflicht eines Pilgers", description = "Diese verletzte Pilgerin schreit irgendwas von einem Beutel.\n\nHabt Ihr einen Beutel in der Nähe gesehen, als Ihr sie gefunden habt? Hmm...\n\nIhre Angreifer müssen sich damit aus dem Staub gemacht haben, als sie sie vertrieben hat. Die Stachelklauenfelshetzer aus der Schlucht im Süden sind bekannt dafür, dass sie einsame Reisende angreifen.\n\nWenn sie sich nicht beruhigt, kann ich ihre Wunden nicht behandeln. Ihre Sturheit könnte sie das Leben kosten.\n\nGeht zur Staubstachelschlucht und haltet nach ihrem Lager Ausschau. Ich möchte wetten, dass sie ihn da verloren hat.", sourceObjective = "Die verletzte Blutelfpilgerin wurde von giftigen Stachelklauenfelshetzern angegriffen, als sie die Staubstachelschlucht erkunden wollte. Findet ihr Lager und haltet nach dem vermissten Beutel Ausschau.", progress = "Die Sache sieht nicht gut aus. So schafft sie es nie wieder auf die Straße. Habt Ihr den Beutel gefunden?", completion = "Vielen Dank, dass Ihr dies zurückgebracht habt, {name}. Ich weiß nicht, was der verletzten Pilgerin an diesem Beutel so wichtig ist, aber sie lässt keinen an sich heran, bis sie ihn wieder hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[9377] = { id = 9377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunger nach Macht", description = "Falkenwacht ist ein stark besuchter Zwischenstopp für alle Pilger auf ihrer langen Reise in die Scherbenwelt. Obwohl wir einer der ersten Außenposten auf dem Weg in die Scherbenwelt sind, erreichen uns viele der Pilger in einem Zustand totaler Erschöpfung, ausgemergelt durch ihre Abhängigkeit.\n\nIn einer Welt wie dieser, versuchen die meisten von ihnen nun ihre Abhängigkeit von der Magie unter Kontrolle zu halten. Essen und Trinken helfen fürs Erste, {class}, doch der Durst nach magischen Energien ist ihr stärkstes Verlangen. Die Überreste von Leerwandlern aus der Scherbenwelt sind eine mächtige Energiequelle, allerdings gibt es nicht viele davon, man findet sie lediglich bei den Sphärenfeldern im Südwesten.", sourceObjective = "Beschafft eine potente Leerwandleressenz von den unkontrollierten Leerwandlern und kehrt anschließend zu Taleris Morgenblick in der Falkenwacht zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9378] = { id = 9378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zitadelle des Schreckens - Naxxramas", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch, dort hineinzugelangen, von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichtegemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mithilfe von einer Art dauerhaften arkanen Tarnung Zugang verschaffen können – einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Diese Tarnung ist allerdings sehr kostspielig. Da Eure Hingabe für die Ziele der Argentumdämmerung jedoch unerschütterlich ist, werden wir Euch sämtliche Kosten erlassen.", sourceObjective = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird Euch die arkane Tarnung kostenfrei gewähren. Euer Ruf bei der Argentumdämmerung muss ehrfürchtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9379] = { id = 9379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkt den Teufelsjäger", description = "Seid gegrüßt, {class}. Sagt ruhig auch 'Hallo' zu Jir'see. Keine Sorge, er wird nicht beißen, solange ich es ihm nicht befehle.\n\n<Angela gurrt dem Teufelsjäger zu.>\n\nEr ist so winzig im Vergleich zu den Sphärenhunden, die hier in der Scherbenwelt leben. Wir werden da allerdings für Abhilfe sorgen, ja, das werden wir, nicht wahr Jir'see?\n\nIch glaube ich weiß jetzt, was es zu tun gilt. Ich brauche jede Menge Blut von den Sphärenhunden. Jetzt zu Eurer Rolle. Während Ihr sie ihm Südosten jagen geht, mache ich alles bereit für das Experi... ähm, die Behandlung.", sourceObjective = "Sammelt 6 Einheiten Sphärenhundblut und bringt sie zu Angela \"Die Klaue\" Kestrel in Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9380] = { id = 9380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hatz nach mehr", description = "Ich sage Euch, sollte ich noch einen Brief von Eisenschmiede bekommen...\n\nHabt Ihr jemals versucht, jemandem etwas zu erklären, der nicht zuhört, {class}? Ich habe den Jungs in Eisenschmiede das von ihnen angeforderte Sphärenhundexemplar geschickt. Jetzt waren sie so frech und haben mir zurückgeschrieben, dass sie ein ganzes \"Rudel\" dieser Viecher möchten! Ein Rudel!\n\nIch habe ihnen also zu erklären versucht, dass Sphärenhunde Einzelgänger sind, aber es schert sie nicht. Ich bin es leid zu diskutieren. In der Gegend östlich der Festung findet Ihr sie. Beschafft sechs der besten und bringt sie hierher zurück?", sourceObjective = "Beschafft 6 unversehrte Sphärenhundkadaver und bringt sie zu Ausgrabungsleiter Murantus in der Ehrenfeste.", sourceObjectiveStatus = "unverified-source-field" }
